// Short human-readable route name for Bazaar discovery (e.g. "/pm/markets" -> "PM Markets").
function shortRouteName(p: string): string {
  return p
    .replace(/^\/+|\/+$/g, "")
    .split("/")
    .map((seg) =>
      seg
        .replace(/[{}]/g, "")
        .split("-")
        .map((w) => (w === "defi" ? "DeFi" : w.length <= 3 ? w.toUpperCase() : w.charAt(0).toUpperCase() + w.slice(1)))
        .join(" ")
    )
    .join(" ");
}

