// First meaningful tag → a short category label, when the route is not in MANIFEST_IO.
// Derived from the catalog's own tags (degrade-open; never a decision gate).
const categoryFromTags = (tags: string[]): string => {
  const t = tags.map((x) => x.toLowerCase());
  if (t.includes("security")) return "security";
  if (t.includes("prediction-markets")) return "prediction-markets";
  if (t.includes("defi") || t.includes("yield")) return "defi";
  if (t.includes("ai") || t.includes("llm")) return "ai";
  if (t.includes("rpc") || t.includes("onchain")) return "blockchain";
  if (t.includes("dns") || t.includes("whois") || t.includes("domain")) return "infrastructure";
  if (t.includes("crypto") || t.includes("funding") || t.includes("prices")) return "crypto";
  return t[0] || "data";
};
// A clean short name derived from the description's first clause, when the route is
// not in MANIFEST_IO — keeps the manifest-ingesting find index from truncating the
// long description into a mid-word run-on name. Capped so it stays a name, not a doc.
const deriveShortName = (desc: string): string => {
  const first = desc.split(/(?<=\?)\s|—| - |\.\s|:\s/)[0].trim();
  const n = first.length > 90 ? first.slice(0, 88).replace(/\s+\S*$/, "") + "…" : first;
  return n || desc.slice(0, 80);
};
// True when the catalog description itself states the route takes no input — a
// reliable textual signal already in the data. Publishing an empty inputSchema for
// these explicitly tells a router "callable with no args" (the easiest to dispatch).
const descSaysNoParams = (desc: string): boolean => /\bno (required )?params\b/i.test(desc);
// Build the additive {name, category, inputSchema, required, example} for a route.
// Never throws; a route with nothing known still yields a derived name + category.
export const manifestCallContract = (
  path: string,
  desc: string,
  tags: string[],
): { name: string; category: string; inputSchema?: Record<string, unknown>; required?: string[]; example?: Record<string, string> } => {
  const io = MANIFEST_IO[path];
  const name = (io && io.name) || deriveShortName(desc);
  const category = (io && io.category) || categoryFromTags(tags);
  const out: { name: string; category: string; inputSchema?: Record<string, unknown>; required?: string[]; example?: Record<string, string> } = { name, category };
  const params = io ? io.params : (descSaysNoParams(desc) ? [] : undefined);
  if (params !== undefined) {
    const properties: Record<string, unknown> = {};
    const required: string[] = [];
    const example: Record<string, string> = {};
    for (const p of params) {
      properties[p.name] = { type: "string", description: p.desc, ...(p.enum ? { enum: p.enum } : {}) };
      if (p.required) required.push(p.name);
      if (p.example !== undefined) example[p.name] = p.example;
    }
    out.inputSchema = { type: "object", properties, ...(required.length ? { required } : {}) };
    if (required.length) out.required = required;
    if (Object.keys(example).length) out.example = example;
  }
  return out;
};

// Self-describing x402 discovery manifest — the standard `.well-known/x402` catalog
// that x402 crawlers/directories read to discover a provider's paid endpoints
// (independent of any facilitator's Bazaar). Lists every paid resource we serve.
const x402ManifestHandler = (c: Context<AppEnv>) => {
  const BASE = "https://x402-data-api.sigrunner.workers.dev";
  const USDC = "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913";
  const payTo = c.env.PAY_TO;
  // Attach a compact sample of what the agent BUYS, pulled from the same
  // RESPONSE_EXAMPLES the OpenAPI serves (no vaporware — real shapes on disk).
  // A browsing buyer-agent decides whether to pay far more readily when it can
  // see the output shape first; competitors (e.g. three.ws) publish an example
  // per paid route in their discovery doc for exactly this reason. Bounded so
  // the manifest stays crawler-friendly: arrays collapse to their first element.
  const sampleOf = (p: string): unknown | undefined => {
    const ex = RESPONSE_EXAMPLES[p];
    if (ex === undefined) return undefined;
    const compact = Array.isArray(ex) ? ex.slice(0, 1) : ex;
    try {
      const s = JSON.stringify(compact);
      // Guard against a pathological large example bloating the manifest.
      if (s.length > 1200) return undefined;
    } catch {
      return undefined;
    }
    return compact;
  };
  const mk = (p: string, method: string, price: string, units: string, desc: string, tags: string[]) => {
  const cc = manifestCallContract(p, desc, tags);
  return {
    x402Version: 2,
    type: "http",
    resource: `${BASE}${p}`,
    methods: [method],
    method,
    // Short, dense, machine-ingestible name — controls the term an x402 find index
    // scores us on instead of truncating the description below into a run-on name.
    name: cc.name,
    description: desc,
    // Primary category label so a catalog that shelves sellers by category resolves us.
    category: cc.category,
    mimeType: "application/json",
    network: NETWORK,
    scheme: "exact",
    payTo,
    price_usdc: price,
    // Machine-readable input contract so a Smart Order Router can CONSTRUCT the paid
    // call (JSON Schema of the query params, which are required, and a runnable
    // example). Present only where known; absent fields degrade open.
    ...(cc.inputSchema !== undefined ? { inputSchema: cc.inputSchema } : {}),
    ...(cc.required !== undefined ? { required: cc.required } : {}),
    ...(cc.example !== undefined ? { example: cc.example } : {}),
    // Free try-before-pay path for auto-wirers that honor it (same shape as paid).
    ...(PREVIEW_ROUTES.has(p) ? { preview_url: `${BASE}${p}/preview` } : {}),
    ...(sampleOf(p) !== undefined ? { outputExample: sampleOf(p) } : {}),
    tags,
    accepts: [
      {
        scheme: "exact", network: NETWORK, amount: units, maxAmountRequired: units,
        asset: USDC, payTo, maxTimeoutSeconds: 300, resource: `${BASE}${p}`,
        description: desc, mimeType: "application/json",
        serviceName: bazaarServiceNameFor(p),
        tags,
        extra: { name: "USD Coin", version: "2", decimals: 6, serviceName: bazaarServiceNameFor(p), tags },
      },
      // Additional EVM networks our same payTo settles via the CDP facilitator (Polygon,
      // Arbitrum) — mirrors the live 402's multi-network accepts[] so a router reading the
      // discovery doc sees every chain it can pay us on. Same dollar price; per-chain USDC
      // asset + EIP-712 domain from @x402/evm DEFAULT_ASSETS.
      ...EXTRA_EVM_SETTLEMENT_NETWORKS.map((net) => {
        const a = EXTRA_NETWORK_USDC[net];
        return {
          scheme: "exact", network: net, amount: units, maxAmountRequired: units,
          asset: a.asset, payTo, maxTimeoutSeconds: 300, resource: `${BASE}${p}`,
          description: desc, mimeType: "application/json",
          serviceName: bazaarServiceNameFor(p),
          tags,
          extra: { name: a.name, version: a.version, decimals: a.decimals, serviceName: bazaarServiceNameFor(p), tags },
        };
      }),
    ],
  };
  };
  return c.json({
    service_overview: {
      name: "Grey Ridge Signals — x402 Data & Security",
      tagline: "Pay-per-call pre-trade token-safety for Base trading agents over x402 — GO/HOLD/BLOCK swap gate and honeypot/due-diligence verdicts, plus live DeFi yields, funding rates, prices, Polymarket and RPC data.",
      description:
        "Pay-per-call x402 for Base agents, led by the pre-trade safety gate: /gate/swap (GO/HOLD/BLOCK sized to your trade, $0.008), /chain/token-report (SAFE/CAUTION/AVOID with measured transfer tax, $0.01) and /chain/token-security (live honeypot/sellability sim, $0.009) — a honeypot check for a fraction of what rival Base token-safety APIs charge (up to $0.25/call). Plus market & on-chain data: /defi/yields (lending/LP yields + IL risk), /crypto/funding (6-venue Binance+Bybit+OKX+Hyperliquid+dYdX+Gate funding + CEX↔DEX arb spread), /crypto/prices, /pm/markets (Polymarket) and 20+ Base RPC/chain routes. Free /preview paths on the flagship routes. No account, no key — agents pay inline in USDC from $0.001/call.",
      website: BASE,
      // Where settlement happens. Base USDC is always live; the authoritative,
      // live-from-the-facilitator set of networks we can actually settle on (support ∩
      // receive-address coverage) is machine-readable at /x402/networks — an agent that
      // filters a catalog by network checks there rather than inferring from one sample.
      settlement: {
        primary_network: NETWORK,
        asset: "USDC",
        capabilities: `${BASE}/x402/networks`,
      },
      categories: ["prediction-markets", "crypto", "data", "security", "mcp", "funding", "yield", "token-price", "rpc", "base", "onchain", "blockchain"],
      // Primary category in the x402 agent-catalog taxonomy used by the Circle Agent
      // Marketplace / CDP discovery API (enum: FINANCIAL_ANALYSIS, PREDICTION_MARKETS,
      // WEB_SEARCH_RESEARCH, SOCIAL_INTELLIGENCE, CREATIVE, INFRASTRUCTURE). Our flagship
      // token-safety + DeFi/market-data routes are FINANCIAL_ANALYSIS — where the lane's
      // data sellers are filed — and we also span PREDICTION_MARKETS (/pm/markets) and
      // INFRASTRUCTURE (Base RPC/chain reads). Stated so a catalog-native agent filtering
      // by the standard enum, or a marketplace reviewer, resolves us to the right shelf.
      category: "FINANCIAL_ANALYSIS",
      catalog_taxonomy: ["FINANCIAL_ANALYSIS", "PREDICTION_MARKETS", "INFRASTRUCTURE"],
      // Measured reliability — the question every integrator asks first (latency/uptime).
      // Sourced from STATUS_SNAPSHOT (scripts/status_report.py over data/uptime_samples.jsonl),
      // surfaced here so a buyer-agent or registry reviewer evaluating trust reads the real
      // number from the machine-readable surface rather than having to ask. Measurement, not an SLA.
      reliability: {
        measured_success_pct: STATUS_SNAPSHOT.overall_success_pct,
        samples: STATUS_SNAPSHOT.window.samples,
        window_from: STATUS_SNAPSHOT.window.from,
        window_to: STATUS_SNAPSHOT.window.to,
        probe: "free /preview paths, every 5 min",
        live_readout: `${BASE}/status`,
        raw_samples: "https://github.com/rezearcher/x402-data-api/blob/main/data/uptime_samples.jsonl",
        note: STATUS_SNAPSHOT.note,
      },
      // Provenance / trust anchors — the fields an auto-indexer or a trust-sensitive
      // buyer-agent checks before calling a seller it has never seen: open-source
      // license, public source repo, machine-readable docs, and a real contact.
      // Every value points to a real artifact (MIT LICENSE in-repo, public GitHub,
      // live OpenAPI, published evidence pack) — no vaporware. Added so discovery
      // surfaces that score sellers on licence/repository signals read them here
      // instead of flagging "unknown".
      provenance: {
        license: "MIT",
        license_url: "https://github.com/rezearcher/x402-data-api/blob/main/LICENSE",
        source_repository: "https://github.com/rezearcher/x402-data-api",
        documentation: `${BASE}/openapi.json`,
        evidence: "https://github.com/rezearcher/x402-data-api/blob/main/docs/EVIDENCE.md",
        contact: "contact@greyridgesignals.ai",
      },
    },
    name: "Grey Ridge Signals",
    provider: "Grey Ridge Signals Group LLC",
    license: "MIT",
    contact: "contact@greyridgesignals.ai",
    documentation: `${BASE}/openapi.json`,
    source_repository: "https://github.com/rezearcher/x402-data-api",
    // Reseller / marketplace attribution — machine-readable so a catalog or router
    // listing our endpoints can auto-tag its referred buyer volume without asking.
    // Append the `ref` param (e.g. ?ref=yourname) to any call URL; the tag rides the
    // x402 402->sign->retry and is recorded on the settled on-chain call, so referred
    // volume is measurable per-tag (real: backed by the TrafficLog `ref` column +
    // getRefStats reconciler). This is the human-readable llms.txt reseller note made
    // machine-readable for auto-wiring marketplaces (e.g. ones ingesting this manifest).
    reseller: {
      attribution_param: "ref",
      example: `${BASE}/gate/swap?token=aero&ref=yourname`,
      note: "Append ?ref=<your-tag> to any call URL to tag referred buyer volume; attributed per-tag on the settled on-chain call.",
      reconcile_contact: "contact@greyridgesignals.ai",
    },
    x402Version: 2,
    network: NETWORK,
    networks: [NETWORK],
    // Demo aliases the PAID handlers accept, published from the same table the
    // handlers and the 402 body resolve through (DEMO_TOKEN_ALIASES). Until
    // t_53e0754d the 402 manifest advertised the canonical address for `usdc`
    // while the paid route 400'd the alias — an agent could negotiate payment and
    // then be refused the product. Now `?token=usdc` is a supported input on the
    // paid route and is documented here so a buyer-agent can discover it.
    demo_token_aliases: DEMO_TOKEN_ALIASES,
    mcp_endpoint: `${BASE}/mcp`,
    // Cross-protocol discovery records so an ERC-8004 / A2A registry crawler
    // (e.g. HOL's Universal Agent Registry protocol-detection, which indexes the
    // "Best x402 Payable" category) ingests this agent as x402-payable on Base
    // directly from the manifest it already reads.
    discovery: {
      a2a_agent_card: `${BASE}/.well-known/agent-card.json`,
      erc8004_registration: `${BASE}/.well-known/erc-8004.json`,
      x402_payable: true,
    },
    // Drop-in framework packages that wrap the earning data routes. A buyer-agent
    // (or the dev reading this manifest) gets the one-line install for its own
    // framework here, at the same place it discovers the routes — so discovery
    // leads straight to an installed, inline-paying tool. See INSTALLABLE_TOOLS.
    integrations: {
      note: "Drop-in framework tools that wrap these routes — install once, every call pays inline over x402 in USDC. No registry account or API key needed; the git URL resolves the package directly.",
      installable_tools: INSTALLABLE_TOOLS,
    },
    // Ordered by observed external demand (sensor snapshot), not catalog
    // declaration order — the arrival channels read this list top-down.
    resources: demandOrderedCatalog().map((r) => mk(...r)),
  });
};
// Standard extension-less path plus the `.json`-suffixed path that stricter
// crawlers probe (returning `noDiscovery` when only the bare path answers).
app.get("/.well-known/x402", x402ManifestHandler);
app.get("/.well-known/x402.json", x402ManifestHandler);

// ---------------------------------------------------------------------------
// agent.json — the Open 402 Directory / Agent Internet Runtime capability
// manifest (spec v1.4, agentinternetruntime.com/spec/agent-json). The directory
// (ArcedeDev/open-402, 18k+ domains, nightly crawl from x402scan + 402index)
// auto-indexes any domain serving `/.well-known/agent.json`; a domain WITHOUT
// one sits as an `unclaimed` blank row (null display_name/description, 0 intents).
// Serving this Tier-2 ("Capable") manifest — version/origin/payout_address plus
// rich intents[] with per-endpoint price + parameters — flips every Grey Ridge
// row to a VERIFIED listing with full metadata (verified = top ~3.7% of the
// directory). Derived entirely from ROUTE_CATALOG + manifestCallContract so it
// never drifts from the real routes, and from STATUS_SNAPSHOT for the measured
// behavioral commitments (Tier 3+ shape, unsigned — honest measurement, not an
// SLA). origin is read from the serving host so each of our hosts emits a
// self-consistent manifest (the validator requires origin == serving domain).
//
// Pure + exported for unit-locking against the real catalog.
export function buildAgentJson(origin: string, payTo: string): Record<string, unknown> {
  // Trim a long route description to a crawler-friendly intent blurb: first
  // sentence, hard-capped — the catalog descriptions can run to paragraphs
  // (preflight is ~1.5k chars) which bloats the manifest and reads poorly in a
  // directory card. No vaporware: it is a prefix of the real description.
  const blurb = (desc: string): string => {
    const firstDot = desc.indexOf(". ");
    let s = firstDot > 0 && firstDot < 220 ? desc.slice(0, firstDot + 1) : desc;
    if (s.length > 240) s = s.slice(0, 237).trimEnd() + "…";
    return s.trim();
  };
  const intents = demandOrderedCatalog().map(([p, method, price, , desc, tags]) => {
    const cc = manifestCallContract(p, desc, tags);
    const intent: Record<string, unknown> = {
      name: cc.name,
      description: blurb(desc),
      endpoint: p,
      method,
      price: { amount: Number(price), currency: "USDC" },
    };
    // Convert the JSON-Schema inputSchema into the agent.json parameters shape:
    // { paramName: { type, required, description } }. Degrades open when a route
    // has no declared params.
    const schema = cc.inputSchema as
      | { properties?: Record<string, { type?: string; description?: string; enum?: string[] }> }
      | undefined;
    const reqd = new Set(cc.required ?? []);
    if (schema && schema.properties && Object.keys(schema.properties).length) {
      const params: Record<string, unknown> = {};
      for (const [name, prop] of Object.entries(schema.properties)) {
        params[name] = {
          type: prop.type || "string",
          required: reqd.has(name),
          description: prop.description || "",
          ...(prop.enum ? { enum: prop.enum } : {}),
        };
      }
      intent.parameters = params;
    }
    // Free try-before-pay path, surfaced per-intent for runtimes that honor it.
    if (PREVIEW_ROUTES.has(p)) intent.preview_endpoint = `${p}/preview`;
    return intent;
  });

  // Measured behavioral invariants (Tier 3+ "commitments" shape, unsigned).
  // Real numbers from the 5-min /preview probe — stated as a measurement, never
  // a contractual SLA (Claims Law).
  const commitments = {
    note: "Measured from a 5-minute free-/preview uptime probe; a measurement, not a contractual SLA.",
    measurement_window: {
      from: STATUS_SNAPSHOT.window.from,
      to: STATUS_SNAPSHOT.window.to,
      samples: STATUS_SNAPSHOT.window.samples,
    },
    entries: [
      {
        type: "availability",
        metric: "measured_success_pct",
        value: STATUS_SNAPSHOT.overall_success_pct,
        unit: "percent",
        source: `https://${origin}/status`,
      },
    ],
  };

  return {
    version: "1.4",
    origin,
    display_name: "Grey Ridge Signals — x402 Data & Security",
    description:
      "Pay-per-call x402 API for Base agents, led by a pre-trade token-safety gate (GO/HOLD/BLOCK honeypot + due-diligence verdicts) plus live DeFi yields, funding rates, prices, Polymarket and Base RPC data. No account or key — agents pay inline in USDC.",
    payout_address: payTo,
    payments: {
      x402: {
        // Derived from the SAME settlement constants that drive the live 402
        // accepts[] and /x402/networks — never a hand-kept single-network list
        // (the no-hardcoded-list law: discovery must not drift from what we can
        // actually settle). Base is primary; the extra EVM networks are the
        // facilitator-supported set our same payTo receives native USDC on, so a
        // routing agent holding USDC on Polygon/Arbitrum sees it can pay us here
        // instead of bouncing off a Base-only manifest.
        networks: [
          { network: "base", asset: "USDC", contract: USDC_BASE },
          ...EXTRA_EVM_SETTLEMENT_NETWORKS.map((chain) => {
            const label = AGENTJSON_NETWORK_LABEL[chain] || chain;
            const meta = EXTRA_NETWORK_USDC[chain];
            return { network: label, asset: "USDC", contract: meta ? meta.asset : "" };
          }),
        ],
        // Payment schemes we honor. Every paid route settles the canonical "exact"
        // scheme; the highest-frequency DATA poller lanes ALSO advertise the canonical
        // "upto" scheme (Permit2 authorize-a-ceiling, settle-actual) at the same price,
        // so a stock x402 client that natively constructs upto/session payments can pay
        // us without the proprietary X-Session-Token rail. Routes derived from the live
        // gate's interop set (no hand-kept list); verify per route in its 402 accepts[].
        schemes: [
          { scheme: "exact", routes: "all paid routes" },
          {
            scheme: "upto",
            routes: UPTO_INTEROP_ROUTES.map((k) => k.replace(/^GET\s+/, "")),
            note: "canonical x402 upto (Permit2 authorize-ceiling, settle-actual) at the same price as exact; CDP-facilitator settled on base/polygon/arbitrum",
          },
        ],
        // The prepaid session-cap rail (shipped): pay one USDC cap, then call any
        // paid route with an X-Session-Token header and NO per-call signature —
        // the capability a high-frequency polling agent is looking for. Surfaced
        // at discovery time so it is chosen, not discovered only after friction.
        session_billing: {
          description:
            "Pay a USDC cap once, then call any paid route with an X-Session-Token header and no per-call signature (collapses the EIP-3009 handshake for high-frequency pollers). 24h TTL.",
          open_endpoint: "/x402/session",
          tiers: [
            { endpoint: "/x402/session", cap: { amount: 0.05, currency: "USDC" } },
            { endpoint: "/x402/session/plus", cap: { amount: 0.5, currency: "USDC" } },
            { endpoint: "/x402/session/max", cap: { amount: 5.0, currency: "USDC" } },
          ],
          balance_check: "/x402/session/status",
        },
      },
    },
    provider: "Grey Ridge Signals Group LLC",
    documentation: `https://${origin}/openapi.json`,
    source_repository: "https://github.com/rezearcher/x402-data-api",
    license: "MIT",
    contact: "contact@greyridgesignals.ai",
    intents,
    commitments,
    extensions: {
      "ai.greyridgesignals": {
        x402_manifest: `https://${origin}/.well-known/x402`,
        mcp_endpoint: `https://${origin}/mcp`,
        settlement_attestation: `https://${origin}/.well-known/x402-settlement-attestation.json`,
      },
    },
  };
}

// Serve the capability manifest at the spec's preferred path and the `/agent.json`
// fallback, plus a `/.well-known/x402.json` alias (some stricter crawlers probe the
// `.json` suffix and return `noDiscovery` when only the extension-less path exists).
const agentJsonHandler = (c: Context<AppEnv>) => {
  const origin = new URL(c.req.url).host;
  const body = buildAgentJson(origin, c.env.PAY_TO);
  return c.json(body, 200, { "cache-control": "public, max-age=300" });
};
app.get("/.well-known/agent.json", agentJsonHandler);
app.get("/agent.json", agentJsonHandler);

// ---------------------------------------------------------------------------
// ai.txt — the x402 Relay (x402-relay.com) Manifest Scanner crawl hook. Per the
// provider docs (x402relay-docs.pages.dev/providers/register), the scanner reads
// `/.well-known/ai.txt` with four fields — x402-endpoint / x402-network /
// x402-asset / x402-price — then probes x402-endpoint for a valid HTTP 402 and
// extracts payTo/network/price/asset to compute a 0-100 Trust Score (protocol 30%
// / uptime 25% / on-chain activity 25% / community 20%). The directory had ZERO
// verified rows (>=70) and ZERO rows with any on-chain txCount when measured
// 2026-11-04 — serving this file is the keyless, zero-capital trigger that enters
// us as the only cat-defi/security row with real settled Base USDC (our payTo has
// genuine on-chain history, unlike every current top-scorer at txCount:0). The
// endpoint we advertise is a route that returns a true 402 bound to PAY_TO (root
// is a 200 landing page, so we point at the top converting data route), keeping
// the price field honest at the route's real $0.001.
//
// CRAWLER-REACHABLE HOST (measured 2026-11-04): the x402 Relay Manifest Scanner —
// like every x402 directory crawler (CDP Bazaar's /validate confirmed this cycle:
// brand host -> 403, workers.dev -> 402) — probes from a datacenter IP, and
// Cloudflare bot-fight on the brand host api.greyridgesignals.ai serves those IPs
// a 403 instead of our 402. An ai.txt served on the brand host that advertises a
// brand-host endpoint therefore hands the scanner a URL it can never verify. So
// the advertised x402-endpoint is PINNED to the crawler-reachable workers.dev host
// regardless of which host serves ai.txt — matching the deliberate `BASE =
// workers.dev` choice already used by every other crawler-facing manifest
// (/.well-known/x402, agent.json discovery). `origin` is kept in the signature for
// the serving-host record but intentionally does not set the probe endpoint.
export function buildAiTxt(origin: string, _payTo: string): string {
  void origin;
  // Point at a route that returns a genuine 402 on a bare GET (the scanner probes
  // this URL directly for the payment-required response); /crypto/prices is our
  // #1 external-payer route, 402s with no query params, and carries payTo in its
  // accepts[]. $0.001 = its real atomic price (1000 / 1e6 USDC), not a teaser.
  const endpoint = `https://x402-data-api.sigrunner.workers.dev/crypto/prices`;
  return [
    `x402-endpoint: ${endpoint}`,
    `x402-network: base`,
    `x402-asset: USDC`,
    `x402-price: 0.001`,
    ``,
  ].join("\n");
}
const aiTxtHandler = (c: Context<AppEnv>) => {
  const origin = new URL(c.req.url).host;
  return c.text(buildAiTxt(origin, c.env.PAY_TO), 200, {
    "content-type": "text/plain; charset=utf-8",
    "cache-control": "public, max-age=300",
  });
};
app.get("/.well-known/ai.txt", aiTxtHandler);
app.get("/ai.txt", aiTxtHandler);

// ---------------------------------------------------------------------------
// x402-verify — ownership-proof file for the x402 Relay directory
// (api.x402-relay.com). When a service is submitted to the directory it is
// "provisional" (not shown in the public /api/services index) until the
// crawler confirms the submitter controls the endpoint host. The directory's
// file-verifier fetches `<origin>/.well-known/x402-verify` and checks that it
// CONTAINS each service's issued token (first 16 hex of the service UUID);
// serving them flips provisional -> verified. Measured 2026-11-05: the
// directory held 214 services with ZERO verified / ZERO on-chain txCount, so a
// verified row backed by our real settled Base USDC payTo is a first-mover
// slot. These tokens are external, directory-issued ownership nonces (not a
// behavioural gate). The verifier's declared github method reads
// `.well-known/x402-verify` and matches `content == token` (we serve a
// superset, which a contains()/line match still verifies).
//
// Primary set (submitted 2026-11-05 pointing at the CRAWLER-REACHABLE
// workers.dev host — the directory crawler probes from a datacenter IP, which
// Cloudflare bot-fight may 403 on the brand host, so the submitted endpoint is
// the workers.dev origin the crawler can actually reach):
//   /crypto/prices  1f3c6cc9-... -> 1f3c6cc95306402d
//   /defi/yields    5be8f5f0-... -> 5be8f5f0b1174ab9
//   /crypto/funding b9a0e97b-... -> b9a0e97baf8d4f7f
// Legacy set (earlier brand-host submissions; kept so their auto-recheck also
// verifies — harmless superset):
//   e54097adb1ee4f4a / 2495d560c63e49c1 / 9547dc438efe41f7
// Served on BOTH hosts by the Worker.
export const X402_RELAY_VERIFY_TOKENS: readonly string[] = [
  "1f3c6cc95306402d",
  "5be8f5f0b1174ab9",
  "b9a0e97baf8d4f7f",
  "e54097adb1ee4f4a",
  "2495d560c63e49c1",
  "9547dc438efe41f7",
];
export function buildX402RelayVerify(): string {
  // Newline-separated plaintext: most file-verifiers do contains(token); the
  // flagship /crypto/prices token is first in case a verifier wants line 1.
  return X402_RELAY_VERIFY_TOKENS.join("\n") + "\n";
}
const x402VerifyHandler = (c: Context<AppEnv>) =>
  c.text(buildX402RelayVerify(), 200, {
    "content-type": "text/plain; charset=utf-8",
    "cache-control": "public, max-age=300",
  });
app.get("/.well-known/x402-verify", x402VerifyHandler);
app.get("/x402-verify", x402VerifyHandler);

app.get("/.well-known/agent-capabilities.json", (c) => {
  const BASE = "https://x402-data-api.sigrunner.workers.dev";
  const q = (c.req.query("q") || "").toLowerCase().trim();
  const limRaw = parseInt(c.req.query("limit") || "3", 10);
  const limit = Number.isFinite(limRaw) ? Math.max(1, Math.min(62, limRaw)) : 3;
  const product = ([p, method, price, _units, desc, tags]: [string, string, string, string, string, string[]]) => ({
    // Canonical id shared with openapi.json so a buyer adapter can resolve this product
    // back to the billable operation when it places the paid call (see canonicalOperationId).
    operation_id: canonicalOperationId(p, method),
    name: "Grey Ridge " + shortRouteName(p),
    use_when: desc.split(/(?<=[.?!])\s/)[0],
    description: desc,
    price_usdc: price,
    source: "Grey Ridge Signals",
    freshness: "real-time",
    method,
    paid_url: `${BASE}${p}`,
    ...(PREVIEW_ROUTES.has(p) ? { preview_url: `${BASE}${p}/preview` } : {}),
    request_schema: `${BASE}/openapi.json`,
    tags,
  });
  // Default (no query) leads with the demand-ordered catalog — same sensor signal as
  // /.well-known/x402 resources[] — so an agent reading the top-N products first sees
  // the routes real buyers pay for. A query overrides with relevance scoring.
  let rows = demandOrderedCatalog();
  if (q) {
    const terms = q.split(/\s+/).filter(Boolean);
    const score = ([p, , , , desc, tags]: [string, string, string, string, string, string[]]) => {
      const hay = (p + " " + desc + " " + tags.join(" ")).toLowerCase();
      return terms.reduce((n, t) => n + (hay.includes(t) ? 1 : 0), 0);
    };
    rows = rows.map((r) => [r, score(r)] as const).filter(([, s]) => s > 0).sort((a, b) => b[1] - a[1]).map(([r]) => r);
  }
  const products = rows.slice(0, limit).map(product);
  return c.json({
    service: "Grey Ridge Signals — x402 Data & Security",
    provider: "Grey Ridge Signals Group LLC",
    contact: "contact@greyridgesignals.ai",
    x402_manifest: `${BASE}/.well-known/x402`,
    openapi: `${BASE}/openapi.json`,
    payment: { protocol: "x402", version: 2, network: NETWORK, asset: "USDC", attribution_param: "ref" },
    query: q || null,
    count: products.length,
    total_available: ROUTE_CATALOG.length,
    products,
    // Same installable-tool index as /.well-known/x402 — both discovery surfaces
    // agree so an agent that lands here finds the one-line install for its framework.
    installable_tools: INSTALLABLE_TOOLS,
  });
});

// ERC-8004 registration-v1 — the on-chain-agent registration file that
// ERC-8004 / A2A discovery crawlers (HOL Universal Agent Registry's
// protocol-detection, the QuickNode ERC-8004 explorer, Agent Arena, Polygon
// Agentic) ingest to classify an agent as x402-payable on Base. Schema matches
// the live registration-v1 files observed on those crawlers (top-level
// x402Support:boolean, pricing{chain,currency,per_task}, services[{name,endpoint}]
// for x402/a2a/MCP, supportedTrust, registrations). This is the machine input
// behind HOL's "Best x402 Payable" discovery category — served keylessly so any
// crawler ingests it without a broker account. `registrations` stays [] until an
// on-chain ERC-8004 identity is minted (Registry Broker step). Every value here
// is a real, live-enforced route/price derived from the same demand-ordered
// catalog as /.well-known/x402 (no hand-kept list that can drift).
app.get("/.well-known/erc-8004.json", (c) => {
  const BASE = "https://x402-data-api.sigrunner.workers.dev";
  const payTo = c.env.PAY_TO;
  // Flagship pre-trade safety gate is the headline product an x402-payable
  // discovery buyer wants; per_task carries it, with the full honest range +
  // per-route pricing in extension fields (prices span $0.001–$0.05).
  const rows = demandOrderedCatalog();
  const prices = rows.map((r) => Number(r[2])).filter((n) => Number.isFinite(n) && n > 0);
  const minP = prices.length ? Math.min(...prices) : 0.001;
  const maxP = prices.length ? Math.max(...prices) : 0.05;
  const flagship = rows.find((r) => r[0] === "/gate/swap");
  const perTask = flagship ? Number(flagship[2]) : minP;
  const routes = rows.map(([p, method, usd, , desc]) => ({
    name: shortRouteName(p),
    endpoint: BASE + p,
    method,
    price_usdc: usd,
    use_when: (desc || "").split(/(?<=[.?!])\s/)[0],
  }));
  return c.json({
    name: "Grey Ridge Signals — x402 Data & Security API",
    type: "https://eips.ethereum.org/EIPS/eip-8004#registration-v1",
    image: "",
    active: true,
    // On-chain identity / settlement address: our live x402 receiving wallet on Base.
    address: payTo,
    agentAddress: payTo,
    pricing: { chain: "base", currency: "USDC", per_task: perTask },
    services: [
      // x402 discovery doc an x402 client reads to find + price every paid route.
      { name: "x402", endpoint: BASE + "/.well-known/x402" },
      // A2A agent-card for Agent-to-Agent protocol discovery.
      { name: "a2a", endpoint: BASE + "/.well-known/agent-card.json" },
      // MCP streamable-HTTP endpoint (same products as MCP tools).
      { name: "MCP", endpoint: BASE + "/mcp" },
    ],
    description:
      "Agent-native, pay-per-call data & pre-trade token safety on Base mainnet (USDC via x402). " +
      "No account, no API key — agents pay inline in USDC per call. Flagship: a one-call pre-trade swap " +
      "gate (honeypot/sellability + pool-sizing, GO/HOLD/BLOCK) at $0.008, ~1/25th the price of comparable " +
      "checks. Plus token-safety verdicts, DeFi yields, perp funding, prediction markets, Base on-chain reads, " +
      "and MCP-server security scanning. Provider: Grey Ridge Signals Group LLC.",
    x402Support: true,
    documentation: BASE + "/llms.txt",
    registrations: [],
    supportedTrust: ["reputation"],
    // --- Grey Ridge extension (non-breaking; canonical parsers ignore unknown keys) ---
    payment: { protocol: "x402", version: 2, network: NETWORK, asset: "USDC" },
    // The settlement-attestation contract an ERC-8004 reputation registry can
    // consume: our dual-RPC 4-check proof emitted in the standard draft-hopley
    // JCS/RFC8785 envelope (the "mechanism specified elsewhere" that draft defers).
    settlement_attestation: {
      format: "draft-hopley-x402-settlement-attestation-01",
      descriptor: BASE + "/.well-known/x402-settlement-attestation.json",
      obtain: BASE + "/x402/receipt-verify?tx=<base-settlement-tx>&url=<x402-endpoint>",
    },
    price_range_usdc: `${minP}-${maxP}`,
    route_count: rows.length,
    routes,
    provider: { name: "Grey Ridge Signals Group LLC", url: BASE, contact: "contact@greyridgesignals.ai" },
  });
});

// ---------------------------------------------------------------------------
// Agent-readiness discovery surfaces — the machine-readable entrypoints an agent
// (or an agent-readiness scanner like Cloudflare's isitagentready.com) expects to
// find by convention. Each points at real capabilities we already serve; none is
// fabricated. Advertised collectively in the root Link header (DISCOVERY_LINK_HEADER).
// ---------------------------------------------------------------------------

// RFC 9727 API Catalog — a linkset that points agents at the OpenAPI description,
// the x402 payment manifest, and the human/agent docs. One hop to every contract.
app.get("/.well-known/api-catalog", (c) => {
  c.header("Content-Type", "application/linkset+json");
  return c.body(
    JSON.stringify({
      linkset: [
        {
          anchor: CANONICAL_ORIGIN + "/",
          "service-desc": [
            { href: CANONICAL_ORIGIN + "/openapi.json", type: "application/json", title: "OpenAPI 3 description" },
          ],
          service: [
            { href: CANONICAL_ORIGIN + "/.well-known/x402", type: "application/json", title: "x402 payment manifest" },
            { href: CANONICAL_ORIGIN + "/mcp", type: "application/json", title: "MCP streamable-HTTP endpoint" },
            { href: CANONICAL_ORIGIN + "/.well-known/x402-settlement-attestation.json", type: "application/json", title: "x402 settlement attestation format (draft-hopley, JCS/RFC8785)" },
          ],
          describedby: [
            { href: CANONICAL_ORIGIN + "/llms.txt", type: "text/plain", title: "Agent catalog (llms.txt)" },
            { href: CANONICAL_ORIGIN + "/.well-known/agent-card.json", type: "application/json", title: "A2A agent card" },
          ],
        },
      ],
    }),
  );
});

// x402 settlement attestation descriptor (free, public). Publishes the contract
// a reputation registry / trust aggregator (ERC-8004, Vouch, TrustGate) uses to
// CONSUME our settlement attestations: the draft-hopley-x402-settlement-
// attestation-01 envelope (JCS/RFC8785, content_hash = SHA256(JCS)), where the
// cryptographic settlement proof the draft punts to "a mechanism specified
// elsewhere" is our dual-RPC 4-check on-chain reconcile. This is the surface that
// makes our output their input instead of a private sixth reputation score.
app.get("/.well-known/x402-settlement-attestation.json", (c) =>
  c.json({
    format: "draft-hopley-x402-settlement-attestation-01",
    canon_version: "jcs-rfc8785-v1",
    canonicalization: "RFC 8785 (JSON Canonicalization Scheme); content_hash = 'sha256:' + hex(SHA256(JCS(envelope without content_hash)))",
    issuer_did: CERT_ISSUER,
    network: "ethereum:8453",
    asset: "USDC.6",
    description:
      "Grey Ridge emits x402 settlement attestations in the standard draft-hopley envelope, carrying a settlement proof produced by an independent dual-RPC, 4-check on-chain reconcile (Transfer-log match + EIP-3009 authorization-consumed cross-confirm, fail-closed on RPC disagreement or an unconsumed nonce). The draft defines the envelope and explicitly defers the crypto settlement proof to 'a mechanism specified elsewhere'; this is that mechanism.",
    required_fields: [
      "settlement_result (SETTLED | PENDING_FINALITY | REVERSED)",
      "settled_payment_ref (sha256:<hex64> of the reconciled on-chain payment record)",
      "settlement_amount { amount_minor, asset_id }",
      "settlement_chain (ethereum:8453)",
      "settlement_provider_did",
      "settlement_timestamp_ms",
      "jurisdiction_flags []",
      "canon_version (jcs-rfc8785-v1)",
      "content_hash (sha256:<hex64>)",
    ],
    obtain: {
      endpoint: CANONICAL_ORIGIN + "/x402/receipt-verify?tx=<base-settlement-tx>&url=<x402-endpoint>",
      field: "attestation",
      note: "Any SETTLED or REVERTED verdict returns a conformant `attestation` object. A single-source (one reachable RPC) SETTLED downgrades to PENDING_FINALITY. Non-settlements (UNDERPAID/WRONG_RECIPIENT/NO_TRANSFER/NOT_FOUND/UNVERIFIED) return attestation:null — no false attestation is ever minted.",
      certificate: CANONICAL_ORIGIN + "/x402/cert?url=<x402-endpoint>&tx=<base-settlement-tx>",
      certificate_field: "settlement_attestation",
    },
    verify: "Re-canonicalize the envelope (drop content_hash) per RFC 8785 and recompute SHA-256 — it must equal content_hash. settled_payment_ref is derived from JCS({chain,tx,payTo,amount_minor,from,nonce,result}).",
    reference: "https://datatracker.ietf.org/doc/draft-hopley-x402-settlement-attestation/",
  }),
);

