// ---------------------------------------------------------------------------
// GET /pm/markets  — Polymarket live prediction-market data  ($0.005)
// Fixed upstream host only (no user-supplied URL) — SSRF-safe by construction.
// ---------------------------------------------------------------------------

interface GammaMarket {
  question?: string;
  slug?: string;
  outcomes?: string;
  outcomePrices?: string;
  volumeNum?: number;
  volume24hr?: number;
  volume1wk?: number;
  liquidityNum?: number;
  endDate?: string;
  active?: boolean;
  bestBid?: number;
  bestAsk?: number;
  spread?: number;
  oneDayPriceChange?: number;
  clobTokenIds?: string;
  conditionId?: string;
}

interface GammaEvent {
  tags?: { label?: string }[];
  markets?: { conditionId?: string }[];
}

interface PolymarketMarket {
  question: string;
  slug: string;
  outcomes: string[];
  outcomePrices: number[];
  volume: number;
  volume24hr: number;
  volume1wk: number;
  liquidity: number;
  endDate: string | null;
  active: boolean;
  bestBid: number | null;
  bestAsk: number | null;
  spread: number | null;
  oneDayPriceChange: number | null;
  clobTokenIds: string[];
  conditionId: string | null;
  tags: string[];
}

// Gamma's outcomes/outcomePrices fields are JSON-encoded strings (double-encoded).
function parseJsonArray<T>(raw: string | undefined): T[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as T[]) : [];
  } catch {
    return [];
  }
}

// Category/tag enrichment: the Gamma /markets object carries no tags itself,
// but the /events object it belongs to does (tags[].label + nested markets[]
// keyed by conditionId). Best-effort — tags are an enrichment, so an upstream
// failure here never fails the underlying market fetch.
async function fetchMarketTags(fetchLimit: number): Promise<Map<string, string[]>> {
  const tagMap = new Map<string, string[]>();
  try {
    // Events are ranked by their own aggregate volume24hr (not per-market), so
    // over-fetch events vs. the market limit to improve conditionId coverage —
    // the Gamma /events endpoint caps out around 100 regardless of a higher limit.
    const eventsLimit = Math.min(fetchLimit * 3, 100);
    const url = `${POLYMARKET_EVENTS_URL}?closed=false&order=volume24hr&ascending=false&limit=${eventsLimit}`;
    const res = await fetch(url, { headers: { accept: "application/json" } });
    if (!res.ok) return tagMap;
    const events = (await res.json()) as GammaEvent[];
    for (const ev of events) {
      const labels = (ev.tags ?? []).map((t) => t.label).filter((l): l is string => !!l);
      for (const m of ev.markets ?? []) {
        if (m.conditionId) tagMap.set(m.conditionId, labels);
      }
    }
  } catch {
    // Keep tagMap empty on any upstream failure — non-fatal enrichment.
  }
  return tagMap;
}

// The Gamma /markets endpoint has no server-side keyword search, so when a
// query is given we pull the top markets by volume24hr and filter client-side.
async function fetchPolymarketMarkets(
  query: string | undefined,
  limit: number,
): Promise<PolymarketMarket[]> {
  const fetchLimit = query ? 100 : limit;
  const url = `${POLYMARKET_URL}?closed=false&limit=${fetchLimit}&order=volume24hr&ascending=false`;

  const [res, tagMap] = await Promise.all([
    fetch(url, { headers: { accept: "application/json" } }),
    fetchMarketTags(fetchLimit),
  ]);
  if (!res.ok) {
    throw new Error(`Polymarket upstream error: ${res.status}`);
  }
  const raw = (await res.json()) as GammaMarket[];

  const normalized: PolymarketMarket[] = raw.map((m) => ({
    question: m.question ?? "",
    slug: m.slug ?? "",
    outcomes: parseJsonArray<string>(m.outcomes),
    outcomePrices: parseJsonArray<string>(m.outcomePrices).map((p) => parseFloat(p)),
    volume: m.volumeNum ?? 0,
    volume24hr: m.volume24hr ?? 0,
    volume1wk: m.volume1wk ?? 0,
    liquidity: m.liquidityNum ?? 0,
    endDate: m.endDate ?? null,
    active: m.active ?? false,
    bestBid: m.bestBid ?? null,
    bestAsk: m.bestAsk ?? null,
    spread: m.spread ?? null,
    oneDayPriceChange: m.oneDayPriceChange ?? null,
    clobTokenIds: parseJsonArray<string>(m.clobTokenIds),
    conditionId: m.conditionId ?? null,
    tags: (m.conditionId && tagMap.get(m.conditionId)) || [],
  }));

  const filtered = query
    ? normalized.filter((m) => m.question.toLowerCase().includes(query.toLowerCase()))
    : normalized;

  return filtered.slice(0, limit);
}

app.get("/pm/markets", async (c) => {
  const query = c.req.query("query") || undefined;
  const limitParam = c.req.query("limit");
  let limit = limitParam ? parseInt(limitParam, 10) : 20;
  if (!Number.isFinite(limit) || limit <= 0) limit = 20;
  limit = Math.min(limit, 100);

  try {
    const markets = await fetchPolymarketMarkets(query, limit);

    console.log(
      JSON.stringify({
        event: "paid_request",
        endpoint: "/pm/markets",
        query: query ?? null,
        limit,
        count: markets.length,
        ts: new Date().toISOString(),
      }),
    );
    const rail = c.get("rail") ?? "x402-paid";
    fireAndForget(c, trackPaidRequest("GET /pm/markets", rail, makeUsageCounter(c.env)));

    return c.json(markets);
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// ---------------------------------------------------------------------------
// CRYPTO/DEFI DATA — Hyperliquid funding, DefiLlama yields, DefiLlama prices.
// All three upstreams are free + keyless; we cap/normalize and charge per call.
// ---------------------------------------------------------------------------

interface HlUniverseEntry {
  name: string;
  szDecimals: number;
  maxLeverage: number;
  isDelisted?: boolean;
}

interface HlAssetCtx {
  funding: string;
  openInterest: string;
  prevDayPx: string;
  dayNtlVlm: string;
  premium: string;
  oraclePx: string;
  markPx: string;
  midPx: string;
}

interface VenueFunding {
  hyperliquid: number | null;
  okx: number | null;
  dydx: number | null;
  binance: number | null;
  bybit: number | null;
  gate: number | null;
}

// Per-venue open interest in USD — the depth behind each venue's funding print.
// Used to screen thin-book outliers out of the arb verdict. null = unmeasured
// (Binance/Bybit geo-block the Worker edge, so their OI is unknown and is never
// used to exclude them — they are major CEXes presumed liquid).
interface VenueOi {
  hyperliquid: number | null;
  okx: number | null;
  dydx: number | null;
  binance: number | null;
  bybit: number | null;
  gate: number | null;
}

// Thin-book OI floor (USD). Below this a venue's funding print is not an
// executable arb: a near-empty book printing an extreme rate counts the same as
// a deep one in a naive cross-venue min/max, overstating the spread and naming a
// venue you cannot get size on as the best long/short. Config constant,
// degrade-open — a venue is excluded only when its OI is KNOWN and below this.
const THIN_OI_FLOOR_USD = 1_000_000;

interface ArbVerdict {
  funding_spread_bps: number | null;
  best_long_venue: string | null;
  best_short_venue: string | null;
  // Venues dropped from the verdict because measured OI is below the floor.
  excluded_thin_venues: { venue: string; open_interest_usd: number }[];
  // true when the verdict was computed over an OI-screened set (>=2 venues
  // survived the floor); false when we fell back to the raw set (degrade-open).
  oi_weighted: boolean;
}

// Pure: compute the CEX<->DEX arb verdict over an OI-SCREENED venue set. A venue
// is excluded from the min/max only when its OI is KNOWN and below the floor;
// venues with unknown OI are kept (degrade-open). Needs >=2 venues to form a
// spread — if screening leaves fewer, falls back to the raw set and flags
// oi_weighted=false so the caller knows the verdict is not OI-screened.
// Exported for unit tests.
export function computeArbVerdict(
  funding: VenueFunding,
  oiUsd: VenueOi,
  floorUsd: number = THIN_OI_FLOOR_USD,
): ArbVerdict {
  const available = (Object.entries(funding) as [string, number | null][]).filter(
    (e): e is [string, number] => e[1] !== null,
  );
  const excluded_thin_venues: { venue: string; open_interest_usd: number }[] = [];
  const screened = available.filter(([venue]) => {
    const oi = (oiUsd as unknown as Record<string, number | null>)[venue];
    if (typeof oi === "number" && Number.isFinite(oi) && oi < floorUsd) {
      excluded_thin_venues.push({ venue, open_interest_usd: Math.round(oi) });
      return false;
    }
    return true;
  });
  const oi_weighted = screened.length >= 2;
  const verdictSet = oi_weighted ? screened : available;
  let funding_spread_bps: number | null = null;
  let best_long_venue: string | null = null;
  let best_short_venue: string | null = null;
  if (verdictSet.length >= 2) {
    const min = verdictSet.reduce((a, b) => (b[1] < a[1] ? b : a));
    const max = verdictSet.reduce((a, b) => (b[1] > a[1] ? b : a));
    funding_spread_bps = Math.round((max[1] - min[1]) * 10000 * 100) / 100;
    best_long_venue = min[0];
    best_short_venue = max[0];
  }
  return { funding_spread_bps, best_long_venue, best_short_venue, excluded_thin_venues, oi_weighted };
}

interface FundingRate {
  coin: string;
  // Each venue's current-period rate at its own native funding interval
  // (Hyperliquid + dYdX = hourly, OKX is typically 8h) — intervals are NOT
  // normalized, this is each venue's rate as-quoted right now.
  funding: VenueFunding;
  // Per-venue open interest in USD (depth behind each funding print).
  open_interest_usd: VenueOi;
  funding_spread_bps: number | null;
  best_long_venue: string | null;
  best_short_venue: string | null;
  // Venues excluded from the arb verdict for a thin (sub-floor) book, and
  // whether the verdict was computed over the OI-screened set.
  excluded_thin_venues: { venue: string; open_interest_usd: number }[];
  oi_weighted: boolean;
  premium: number | null;
  annualized_hl: number | null;
  annualized_okx: number | null;
  annualized_binance: number | null;
  annualized_bybit: number | null;
  annualized_gate: number | null;
  signal: "LONGS_PAY" | "SHORTS_PAY" | "NEUTRAL";
  next_funding_ts: number | null;
  markPx: number;
  oraclePx: number;
  openInterest: number;
  dayNtlVlm: number;
}

interface OkxFundingResult {
  rate: number | null;
  nextFundingTs: number | null;
}

async function fetchOkxFunding(coin: string): Promise<OkxFundingResult> {
  try {
    const res = await fetch(`https://www.okx.com/api/v5/public/funding-rate?instId=${coin}-USDT-SWAP`);
    if (!res.ok) return { rate: null, nextFundingTs: null };
    const j = (await res.json()) as {
      code: string;
      data?: { fundingRate: string; nextFundingTime?: string }[];
    };
    if (j.code !== "0" || !j.data?.[0]) return { rate: null, nextFundingTs: null };
    const rate = parseFloat(j.data[0].fundingRate);
    const nextFundingTs = j.data[0].nextFundingTime ? parseInt(j.data[0].nextFundingTime, 10) : null;
    return {
      rate: Number.isFinite(rate) ? rate : null,
      nextFundingTs: Number.isFinite(nextFundingTs as number) ? nextFundingTs : null,
    };
  } catch {
    return { rate: null, nextFundingTs: null };
  }
}

// Gate.io USDT-margined perp (api.gateio.ws, keyless). Contract id is `{coin}_USDT`
// (e.g. BTC_USDT); `funding_rate` is the current period as a native fraction
// string, and open interest in USD = position_size (contracts) * quanto_multiplier
// (base per contract) * mark_price (USD per base) — all three live in the one
// contract payload, so funding + OI come from a single fetch. Gate funds every
// 8h. Best-effort + degrade-open.
async function fetchGateContract(coin: string): Promise<{ rate: number | null; oiUsd: number | null }> {
  try {
    const res = await fetch(`https://api.gateio.ws/api/v4/futures/usdt/contracts/${coin}_USDT`, {
      headers: { accept: "application/json" },
    });
    if (!res.ok) return { rate: null, oiUsd: null };
    const j = (await res.json()) as {
      funding_rate?: string;
      position_size?: number;
      quanto_multiplier?: string;
      mark_price?: string;
    };
    const rate = parseFloat(String(j.funding_rate));
    const size = Number(j.position_size);
    const mult = parseFloat(String(j.quanto_multiplier));
    const mark = parseFloat(String(j.mark_price));
    const oiUsd =
      Number.isFinite(size) && Number.isFinite(mult) && Number.isFinite(mark) ? size * mult * mark : null;
    return { rate: Number.isFinite(rate) ? rate : null, oiUsd };
  } catch {
    return { rate: null, oiUsd: null };
  }
}

// OKX open interest in USD (keyless; `oiUsd` is published directly).
async function fetchOkxOpenInterestUsd(coin: string): Promise<number | null> {
  try {
    const res = await fetch(`https://www.okx.com/api/v5/public/open-interest?instId=${coin}-USDT-SWAP`);
    if (!res.ok) return null;
    const j = (await res.json()) as { code: string; data?: { oiUsd?: string }[] };
    if (j.code !== "0" || !j.data?.[0]) return null;
    const usd = parseFloat(String(j.data[0].oiUsd));
    return Number.isFinite(usd) ? usd : null;
  } catch {
    return null;
  }
}

// dYdX v4 open interest in USD = openInterest (base) * oraclePrice (the indexer
// does not publish a USD figure; openInterestUsd is null).
async function fetchDydxOpenInterestUsd(coin: string): Promise<number | null> {
  try {
    const res = await fetch(`https://indexer.dydx.trade/v4/perpetualMarkets?ticker=${coin}-USD`);
    if (!res.ok) return null;
    const j = (await res.json()) as {
      markets?: Record<string, { openInterest?: string; oraclePrice?: string }>;
    };
    const m = j.markets?.[`${coin}-USD`];
    if (!m) return null;
    const oi = parseFloat(String(m.openInterest));
    const px = parseFloat(String(m.oraclePrice));
    return Number.isFinite(oi) && Number.isFinite(px) ? oi * px : null;
  } catch {
    return null;
  }
}

// NOTE: Bitget (api.bitget.com) is NOT wired as a venue — it returns a 403
// CloudFront country-block from Cloudflare datacenter egress (verified live via
// the `?debug=venues` probe below), the same geo-block that forces the
// Hyperliquid bridge for Binance/Bybit — and Hyperliquid's predictedFundings
// does not carry Bitget, so there is no keyless bridge. The probe still checks
// Bitget each call so a future cycle re-wires it in one fetcher if the block lifts.

// Edge-reachability probe for the candidate venues. Run FROM the Worker (via the
// free preview `?debug=venues`) to learn whether a datacenter-egress upstream is
// geo-blocked (403) before we advertise it as a covered venue — some CEX perp
// APIs country-block Cloudflare IPs (Binance/Bybit do; hence the HL bridge).
// Honest-gate only: never shipped to paying callers, never changes the feed.
async function probeVenue(url: string): Promise<{ ok: boolean; status: number | string; sample: string }> {
  try {
    const res = await fetch(url, { headers: { accept: "application/json" } });
    const text = await res.text();
    return { ok: res.ok, status: res.status, sample: text.slice(0, 180) };
  } catch (e) {
    return { ok: false, status: "fetch_error", sample: String((e as Error).message).slice(0, 180) };
  }
}

// Signal is derived off Hyperliquid's rate — the one venue always present.
function fundingSignal(hlFunding: number): "LONGS_PAY" | "SHORTS_PAY" | "NEUTRAL" {
  if (!Number.isFinite(hlFunding) || Math.abs(hlFunding) < 1e-8) return "NEUTRAL";
  return hlFunding > 0 ? "LONGS_PAY" : "SHORTS_PAY";
}

// CoinGecko's public API 403s any request without a descriptive User-Agent
// (Cloudflare Workers send none by default), so every api.coingecko.com fetch
// must carry this header or it silently fails.
const CG_HEADERS = {
  "User-Agent": "grey-ridge-x402-data/1.0 (+https://greyridgesignals.ai)",
  accept: "application/json",
};

// Binance + Bybit perp APIs (fapi.binance.com, api.bybit.com, www.binance.com,
// api.bytick.com) ALL geo-block Cloudflare/datacenter egress (403 CloudFront
// country-block — confirmed live from the edge), and CoinGecko's derivatives
// endpoint 429-rate-limits the shared Worker IP. The clean bridge is
// Hyperliquid's own `predictedFundings` endpoint: it publishes, per coin, the
// current predicted funding on BinPerp (Binance), BybitPerp (Bybit) and HlPerp
// alongside each venue's funding interval, as native fractions. It's keyless,
// NOT geo-blocked, NOT rate-limited (the same host we already hit for the HL
// universe), ~64KB in one POST, and shares Hyperliquid's coin namespace so it
// maps 1:1 onto our universe. Best-effort + degrade-open: any failure yields an
// empty map and those venues resolve null, never failing the request.
interface VenuePredicted {
  binance: number | null;
  bybit: number | null;
  binanceIntervalH: number | null;
  bybitIntervalH: number | null;
}
// Pure: reduce Hyperliquid's predictedFundings payload — an array of
// [coin, [[venueName, {fundingRate, fundingIntervalHours}], ...]] — to a
// coin -> {binance, bybit, intervals} map. Exported for unit tests.
export function parsePredictedFundings(raw: unknown): Map<string, VenuePredicted> {
  const m = new Map<string, VenuePredicted>();
  if (!Array.isArray(raw)) return m;
  for (const row of raw) {
    if (!Array.isArray(row) || row.length < 2) continue;
    const coin = typeof row[0] === "string" ? row[0] : null;
    const venues = row[1];
    if (!coin || !Array.isArray(venues)) continue;
    const entry: VenuePredicted = { binance: null, bybit: null, binanceIntervalH: null, bybitIntervalH: null };
    for (const v of venues) {
      if (!Array.isArray(v) || v.length < 2) continue;
      const name = v[0];
      const info = v[1] as { fundingRate?: unknown; fundingIntervalHours?: unknown } | null;
      if (!info || typeof info !== "object") continue;
      const rate = parseFloat(String(info.fundingRate));
      if (!Number.isFinite(rate)) continue;
      const ivRaw = Number(info.fundingIntervalHours);
      const iv = Number.isFinite(ivRaw) && ivRaw > 0 ? ivRaw : null;
      if (name === "BinPerp") { entry.binance = rate; entry.binanceIntervalH = iv; }
      else if (name === "BybitPerp") { entry.bybit = rate; entry.bybitIntervalH = iv; }
    }
    m.set(coin, entry);
  }
  return m;
}
async function fetchPredictedFundings(): Promise<Map<string, VenuePredicted>> {
  try {
    const res = await fetch("https://api.hyperliquid.xyz/info", {
      method: "POST",
      headers: { "content-type": "application/json", accept: "application/json" },
      body: JSON.stringify({ type: "predictedFundings" }),
    });
    if (!res.ok) return new Map();
    return parsePredictedFundings(await res.json());
  } catch {
    return new Map();
  }
}
// Annualize a per-period funding rate using its native funding interval
// (periods/day = 24/intervalHours), falling back to an 8h CEX interval.
function annualizeFunding(rate: number | null, intervalH: number | null): number | null {
  if (rate === null) return null;
  const iv = intervalH && intervalH > 0 ? intervalH : 8;
  return rate * (24 / iv) * 365;
}

// dYdX v4 (indexer, keyless, no CF block) — its coin tickers (`{coin}-USD`) map
// 1:1 onto Hyperliquid's `coin` names.
async function fetchDydxFunding(coin: string): Promise<number | null> {
  try {
    const res = await fetch(`https://indexer.dydx.trade/v4/historicalFunding/${coin}-USD?limit=1`);
    if (!res.ok) return null;
    const j = (await res.json()) as { historicalFunding?: { rate: string }[] };
    const rate = parseFloat(j.historicalFunding?.[0]?.rate ?? "");
    return Number.isFinite(rate) ? rate : null;
  } catch {
    return null;
  }
}

async function fetchFundingRates(limit: number): Promise<FundingRate[]> {
  const res = await fetch("https://api.hyperliquid.xyz/info", {
    method: "POST",
    headers: { "content-type": "application/json", accept: "application/json" },
    body: JSON.stringify({ type: "metaAndAssetCtxs" }),
  });
  if (!res.ok) {
    throw new Error(`Hyperliquid upstream error: ${res.status}`);
  }
  const [meta, ctxs] = (await res.json()) as [{ universe: HlUniverseEntry[] }, HlAssetCtx[]];

  const hlRates: {
    coin: string;
    hlFunding: number;
    premium: number | null;
    markPx: number;
    oraclePx: number;
    openInterest: number;
    dayNtlVlm: number;
  }[] = [];
  meta.universe.forEach((u, i) => {
    if (u.isDelisted) return;
    const ctx = ctxs[i];
    if (!ctx) return;
    const premium = parseFloat(ctx.premium);
    hlRates.push({
      coin: u.name,
      hlFunding: parseFloat(ctx.funding),
      premium: Number.isFinite(premium) ? premium : null,
      markPx: parseFloat(ctx.markPx),
      oraclePx: parseFloat(ctx.oraclePx),
      openInterest: parseFloat(ctx.openInterest),
      dayNtlVlm: parseFloat(ctx.dayNtlVlm),
    });
  });

  hlRates.sort((a, b) => b.dayNtlVlm - a.dayNtlVlm);
  const top = hlRates.slice(0, limit);

  // The two top CEX perp venues (Binance, Bybit) come from Hyperliquid's
  // predictedFundings endpoint — one keyless, non-geoblocked POST, indexed by coin.
  const cex = await fetchPredictedFundings();

  // Cross-venue enrichment: Hyperliquid is always present (it's the coin
  // universe). OKX/dYdX/Binance/Bybit are best-effort — each lookup is wrapped so an
  // upstream error or an unlisted coin on any venue never fails the request.
  const rates: FundingRate[] = await Promise.all(
    top.map(async (r) => {
      const [okxRes, dydxRes, gateRes, okxOiRes, dydxOiRes] = await Promise.allSettled([
        fetchOkxFunding(r.coin),
        fetchDydxFunding(r.coin),
        fetchGateContract(r.coin),
        fetchOkxOpenInterestUsd(r.coin),
        fetchDydxOpenInterestUsd(r.coin),
      ]);
      const okx: OkxFundingResult = okxRes.status === "fulfilled" ? okxRes.value : { rate: null, nextFundingTs: null };
      const gate = gateRes.status === "fulfilled" ? gateRes.value : { rate: null, oiUsd: null };
      const cx = cex.get(r.coin);
      const funding: VenueFunding = {
        hyperliquid: r.hlFunding,
        okx: okx.rate,
        dydx: dydxRes.status === "fulfilled" ? dydxRes.value : null,
        binance: cx?.binance ?? null,
        bybit: cx?.bybit ?? null,
        gate: gate.rate,
      };

      // Per-venue open interest (USD). Hyperliquid comes from the assetCtx we
      // already hold (base OI * oracle price); OKX/dYdX/Gate are fetched above;
      // Binance/Bybit geo-block the edge so their OI is unmeasured (null).
      const hlOiUsd = r.openInterest * r.oraclePx;
      const oiUsd: VenueOi = {
        hyperliquid: Number.isFinite(hlOiUsd) ? Math.round(hlOiUsd) : null,
        okx: okxOiRes.status === "fulfilled" && okxOiRes.value !== null ? Math.round(okxOiRes.value) : null,
        dydx: dydxOiRes.status === "fulfilled" && dydxOiRes.value !== null ? Math.round(dydxOiRes.value) : null,
        binance: null,
        bybit: null,
        gate: gate.oiUsd !== null ? Math.round(gate.oiUsd) : null,
      };

      // Arb verdict over the OI-screened venue set — a thin-book funding outlier
      // never names an unexecutable best long/short or inflates the spread.
      const verdict = computeArbVerdict(funding, oiUsd);

      return {
        coin: r.coin,
        funding,
        open_interest_usd: oiUsd,
        funding_spread_bps: verdict.funding_spread_bps,
        best_long_venue: verdict.best_long_venue,
        best_short_venue: verdict.best_short_venue,
        excluded_thin_venues: verdict.excluded_thin_venues,
        oi_weighted: verdict.oi_weighted,
        premium: r.premium,
        annualized_hl: funding.hyperliquid !== null ? funding.hyperliquid * 24 * 365 : null,
        annualized_okx: funding.okx !== null ? funding.okx * 3 * 365 : null,
        annualized_binance: annualizeFunding(funding.binance, cx?.binanceIntervalH ?? null),
        annualized_bybit: annualizeFunding(funding.bybit, cx?.bybitIntervalH ?? null),
        annualized_gate: annualizeFunding(funding.gate, 8),
        signal: fundingSignal(r.hlFunding),
        next_funding_ts: okx.nextFundingTs,
        markPx: r.markPx,
        oraclePx: r.oraclePx,
        openInterest: r.openInterest,
        dayNtlVlm: r.dayNtlVlm,
      };
    }),
  );

  return rates;
}

app.get("/crypto/funding", async (c) => {
  const limitParam = c.req.query("limit");
  let limit = limitParam ? parseInt(limitParam, 10) : 20;
  if (!Number.isFinite(limit) || limit <= 0) limit = 20;
  limit = Math.min(limit, 100);

  try {
    const rates = await fetchFundingRates(limit);

    console.log(
      JSON.stringify({
        event: "paid_request",
        endpoint: "/crypto/funding",
        limit,
        count: rates.length,
        ts: new Date().toISOString(),
      }),
    );
    const rail = c.get("rail") ?? "x402-paid";
    fireAndForget(c, trackPaidRequest("GET /crypto/funding", rail, makeUsageCounter(c.env)));

    return c.json(rates);
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

interface DefiLlamaPool {
  chain: string;
  project: string;
  symbol: string;
  tvlUsd: number;
  apyBase: number | null;
  apyReward: number | null;
  apy: number | null;
  apyPct1D: number | null;
  apyPct7D: number | null;
  apyPct30D: number | null;
  apyBase7d: number | null;
  apyMean30d: number | null;
  pool: string;
  stablecoin: boolean;
  ilRisk: string;
  il7d: number | null;
  exposure: string;
  volumeUsd1d: number | null;
  outlier: boolean;
  rewardTokens: string[] | null;
  underlyingTokens: string[] | null;
  mu: number | null;
  sigma: number | null;
  predictions?: { predictedProbability: number | null; predictedClass?: string | null };
}

interface YieldPool {
  project: string;
  chain: string;
  symbol: string;
  pool: string;
  apy: number | null;
  apyBase: number | null;
  apyReward: number | null;
  apyPct1D: number | null;
  apyPct7D: number | null;
  apyPct30D: number | null;
  apyBase7d: number | null;
  apyMean30d: number | null;
  tvlUsd: number;
  stablecoin: boolean;
  ilRisk: string;
  il7d: number | null;
  exposure: string;
  outlier: boolean;
  rewardTokens: string[] | null;
  underlyingTokens: string[] | null;
  mu: number | null;
  sigma: number | null;
  risk_adjusted_apy: number | null;
  predicted_probability: number | null;
  predicted_class: string | null;
  volumeUsd1d: number | null;
}

// Match a DefiLlama pool's project slug against a caller-supplied filter by
// exact slug OR by protocol family name. DefiLlama namespaces protocols as
// "<family>-<version>" (aave-v3, uniswap-v2, curve-dex), so an agent asking
// for the human name (project=aave) must still resolve the versioned pools
// instead of silently getting [] on a paid route. The trailing dash keeps the
// family match precise: "aave" -> {aave-v3, aave-v4} and "curve" -> {curve-dex,
// curve-llamalend}, but "uni" does NOT match "uniswap" and a bogus name still
// returns [] (degrade-open, no hardcoded protocol list — derived from the
// upstream naming convention).
export function matchesProjectFamily(slug: string, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  const s = slug.toLowerCase();
  return s === q || s.startsWith(`${q}-`);
}

// DefiLlama identifies chains by a canonical display name ("Ethereum", "OP
// Mainnet", "Avalanche", "BSC", "Hyperliquid L1"), but a trading agent filtering
// yields naturally passes the short ticker/abbreviation it uses everywhere else
// (chain=eth, arb, op, avax, matic, sol, bnb). Those never equal the canonical
// name, so the exact-match chain filter below returned an empty array on a PAID
// route = silent count=0 success = a churned repeat buyer on our #1 earning
// route. This maps the natural abbreviation to the canonical name (both sides
// compared lowercased). Same footgun CLASS as the ticker-symbol (crypto/prices)
// and protocol-family (defi/yields) resolvers already shipped.
//
// Degrade-open and precise: an exact canonical name an agent already passes
// ("Ethereum", "op mainnet") is NOT in the table and falls through unchanged, so
// results are byte-identical; a bogus chain still returns [] via the exact
// filter. It is a normalization alias TABLE (config/data derived from upstream
// naming), not a decision gate — unknown input passes through, nothing is
// silently dropped (CLAUDE.md no-hardcoded-list-as-logic is satisfied).
const CHAIN_ALIASES: Record<string, string> = {
  eth: "ethereum", ether: "ethereum", "ethereum-mainnet": "ethereum", "eth-mainnet": "ethereum", mainnet: "ethereum",
  arb: "arbitrum", "arbitrum-one": "arbitrum",
  op: "op mainnet", optimism: "op mainnet", optimistic: "op mainnet", opmainnet: "op mainnet", "op-mainnet": "op mainnet",
  avax: "avalanche", "avalanche-c": "avalanche",
  matic: "polygon", poly: "polygon", "polygon-pos": "polygon",
  sol: "solana",
  bnb: "bsc", binance: "bsc", "binance-smart-chain": "bsc", "bnb-chain": "bsc", bnbchain: "bsc",
  hl: "hyperliquid l1", hyperliquid: "hyperliquid l1", hyperliquidl1: "hyperliquid l1", "hyperliquid-l1": "hyperliquid l1",
  osmo: "osmosis",
  bera: "berachain",
  ftm: "fantom",
  xdai: "gnosis", gnosischain: "gnosis",
  trx: "tron",
  hbar: "hedera",
  algo: "algorand",
  plume: "plume mainnet",
  dot: "polkadot",
  cro: "cronos",
  mnt: "mantle",
  apt: "aptos",
  ada: "cardano",
  zksync: "zksync era", zks: "zksync era", "zksync-era": "zksync era", zksyncera: "zksync era", era: "zksync era",
  strk: "starknet",
};

// Returns the lowercased canonical DefiLlama chain name for an agent-supplied
// chain filter; empty/whitespace -> "" (no filter). All callers compare against
// pool.chain.toLowerCase(), so the returned value is always lowercase.
export function resolveChainAlias(query: string): string {
  const q = (query ?? "").trim().toLowerCase();
  if (!q) return "";
  return CHAIN_ALIASES[q] ?? q;
}

// Normalize one raw DefiLlama pool into our YieldPool shape. Extracted so both
// the ranked /defi/yields list and the single-pool /defi/yield-entry-verdict
// lookup share ONE normalization (incl. the stability forecast class/probability
// the verdict logic reads) — no drift between list rows and the verdict input.
export function normalizeDefiLlamaPool(p: DefiLlamaPool): YieldPool {
  return {
    project: p.project,
    chain: p.chain,
    symbol: p.symbol,
    pool: p.pool,
    apy: p.apy,
    apyBase: p.apyBase,
    apyReward: p.apyReward,
    apyPct1D: p.apyPct1D ?? null,
    apyPct7D: p.apyPct7D ?? null,
    apyPct30D: p.apyPct30D ?? null,
    apyBase7d: p.apyBase7d ?? null,
    apyMean30d: p.apyMean30d ?? null,
    tvlUsd: p.tvlUsd ?? 0,
    stablecoin: p.stablecoin ?? false,
    ilRisk: p.ilRisk ?? "unknown",
    il7d: p.il7d ?? null,
    exposure: p.exposure ?? "unknown",
    outlier: p.outlier ?? false,
    rewardTokens: p.rewardTokens ?? null,
    underlyingTokens: p.underlyingTokens ?? null,
    mu: p.mu ?? null,
    sigma: p.sigma ?? null,
    risk_adjusted_apy: p.apy != null && p.sigma ? p.apy / p.sigma : null,
    predicted_probability: p.predictions?.predictedProbability ?? null,
    predicted_class: p.predictions?.predictedClass ?? null,
    volumeUsd1d: p.volumeUsd1d ?? null,
  };
}

async function fetchDefiYields(
  limit: number,
  project: string | undefined,
  chain: string | undefined,
  stableOnly: boolean,
  sort: "tvl" | "risk_adjusted" = "tvl",
): Promise<YieldPool[]> {
  const res = await fetch("https://yields.llama.fi/pools", { headers: { accept: "application/json" } });
  if (!res.ok) {
    throw new Error(`DefiLlama yields upstream error: ${res.status}`);
  }
  const raw = (await res.json()) as { status: string; data: DefiLlamaPool[] };

  const normalized: YieldPool[] = raw.data.map(normalizeDefiLlamaPool);

  const wantChain = resolveChainAlias(chain ?? "");
  const filtered = normalized.filter((p) => {
    if (project && !matchesProjectFamily(p.project, project)) return false;
    if (wantChain && p.chain.toLowerCase() !== wantChain) return false;
    if (stableOnly && !p.stablecoin) return false;
    return true;
  });

  const sorted = filtered.sort((a, b) =>
    sort === "risk_adjusted"
      ? (b.risk_adjusted_apy ?? -Infinity) - (a.risk_adjusted_apy ?? -Infinity)
      : (b.tvlUsd ?? 0) - (a.tvlUsd ?? 0),
  );

  return sorted.slice(0, limit);
}

app.get("/defi/yields", async (c) => {
  const limitParam = c.req.query("limit");
  let limit = limitParam ? parseInt(limitParam, 10) : 20;
  if (!Number.isFinite(limit) || limit <= 0) limit = 20;
  limit = Math.min(limit, 100);
  const project = c.req.query("project") || undefined;
  const chain = c.req.query("chain") || undefined;
  const stable = c.req.query("stable") === "true";
  const sort = c.req.query("sort") === "risk_adjusted" ? "risk_adjusted" : "tvl";

  try {
    const pools = await fetchDefiYields(limit, project, chain, stable, sort);

    // Lead with provenance — the one axis DefiLlama's free /pools and every x402
    // yield seller (Yield.xyz, the clones) cannot match: they return the pool's
    // APY right now; we return "we've tracked THIS pool since <t>, here is its APY
    // trajectory and change-since-first". History you never stored cannot be
    // reconstructed after the fact. Keyed by the stable DefiLlama poolId, value =
    // live APY. Writes are throttled + degrade-open, so an enriched array is
    // best-effort: a pool without `.provenance` still carries its full APY fields
    // (never a breaking change to the array shape). Skipped when apy is non-finite
    // (a junk reading must not seed a series — appendTick guards it too).
    const enriched = await Promise.all(
      pools.map(async (p) => {
        // Decision tag first (pure, deterministic over the pool's own fields),
        // then the provenance archive (throttled + degrade-open). A row keeps its
        // full APY fields regardless of which enrichment is available.
        const v = yieldRowVerdict(p);
        let row: YieldPool & { verdict?: YieldEntryVerdict; risk_score?: number; provenance?: unknown } =
          v ? { ...p, verdict: v.verdict, risk_score: v.risk_score } : { ...p };
        if (p.pool && typeof p.apy === "number" && Number.isFinite(p.apy)) {
          const prov = await archiveProvenance(c, "yield", p.pool, p.apy);
          if (prov) row = { ...row, provenance: prov };
        }
        return row;
      }),
    );

    console.log(
      JSON.stringify({
        event: "paid_request",
        endpoint: "/defi/yields",
        limit,
        project: project ?? null,
        chain: chain ?? null,
        stable,
        sort,
        count: pools.length,
        ts: new Date().toISOString(),
      }),
    );
    const rail = c.get("rail") ?? "x402-paid";
    fireAndForget(c, trackPaidRequest("GET /defi/yields", rail, makeUsageCounter(c.env)));

    return c.json(enriched);
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// Fetch a single DefiLlama pool by its poolId. DefiLlama's /pools has no id
// filter, so we fetch-all (same upstream as fetchDefiYields) and find by id.
// Returns null when the id isn't in DefiLlama's universe (degrade-open — the
// caller turns that into verdict:null, never a throw).
export async function fetchDefiPoolById(poolId: string): Promise<YieldPool | null> {
  const res = await fetch("https://yields.llama.fi/pools", { headers: { accept: "application/json" } });
  if (!res.ok) {
    throw new Error(`DefiLlama yields upstream error: ${res.status}`);
  }
  const raw = (await res.json()) as { status: string; data: DefiLlamaPool[] };
  const p = raw.data.find((x) => x.pool === poolId);
  return p ? normalizeDefiLlamaPool(p) : null;
}

export type YieldEntryVerdict = "SUSTAINABLE" | "DECAYING" | "OUTLIER" | "AVOID";
export interface YieldEntryReason { code: string; detail: string; field: string }
export interface YieldEntryVerdictResult {
  pool: string;
  project: string;
  chain: string;
  symbol: string;
  verdict: YieldEntryVerdict;
  risk_score: number;
  reasons: YieldEntryReason[];
  apy: number | null;
  apyPct7D: number | null;
  apyPct30D: number | null;
  il7d: number | null;
  ilRisk: string;
  sigma: number | null;
  risk_adjusted_apy: number | null;
  predicted: { class: string | null; probability: number | null };
  tvlUsd: number;
}

// Per-pool entry verdict — the should-I-enter-THIS-pool call that neither
// DefiLlama (raw fields only) nor GoPlus (token-safety only) nor any x402 seller
// packages. Pure + deterministic over the pool's OWN DefiLlama fields (no network,
// no hardcoded pool list): every threshold is a named constant and every reason
// cites the field that drove it. Worst-verdict-wins precedence:
//   OUTLIER (DefiLlama's own statistical-artifact flag — APY likely not real)
//   > AVOID (collapsing/down forecast, or dangerously illiquid)
//   > DECAYING (meaningful negative APY trend / volatile)
//   > SUSTAINABLE (stable-or-up, liquid, trend intact).
// risk_score (0-100, higher = worse) is the additive sum of the triggered
// factors, capped — it quantifies the verdict for sizing.
export const YIELD_ENTRY_THRESHOLDS = {
  DOWN_PROB_AVOID: 60,       // predictedClass "Down" with ≥ this probability → AVOID
  APY_30D_COLLAPSE: -50,     // apyPct30D ≤ this (%) → APY has collapsed → AVOID
  TVL_ILLIQUID: 50_000,      // tvlUsd < this → exit-liquidity risk
  APY_7D_DECAY: -40,         // apyPct7D ≤ this (%) → DECAYING
  APY_30D_DECAY: -25,        // apyPct30D ≤ this (%) → DECAYING
  SIGMA_VOLATILE: 0.5,       // sigma ≥ this → APY is volatile
  IL7D_HIGH: 5,              // |il7d| ≥ this (%) → material impermanent-loss drag
} as const;

export function computeYieldEntryVerdict(pool: YieldPool): YieldEntryVerdictResult {
  const T = YIELD_ENTRY_THRESHOLDS;
  const reasons: YieldEntryReason[] = [];
  let score = 0;
  const num = (v: number | null | undefined): number | null =>
    typeof v === "number" && Number.isFinite(v) ? v : null;

  const apy = num(pool.apy);
  const apy7 = num(pool.apyPct7D);
  const apy30 = num(pool.apyPct30D);
  const il7 = num(pool.il7d);
  const sigma = num(pool.sigma);
  const tvl = num(pool.tvlUsd) ?? 0;
  const pClass = pool.predicted_class ?? null;
  const pProb = num(pool.predicted_probability);

  let verdict: YieldEntryVerdict = "SUSTAINABLE";
  const worse = (v: YieldEntryVerdict) => {
    const rank: Record<YieldEntryVerdict, number> = { SUSTAINABLE: 0, DECAYING: 1, AVOID: 2, OUTLIER: 3 };
    if (rank[v] > rank[verdict]) verdict = v;
  };

  // OUTLIER — DefiLlama's own flag that the advertised APY is a statistical
  // artifact (reward spike, thin pool), i.e. not a yield you can actually earn.
  if (pool.outlier === true) {
    worse("OUTLIER");
    score += 45;
    reasons.push({ code: "statistical_outlier", detail: "DefiLlama flags this pool's APY as a statistical outlier — the advertised rate is likely a data artifact, not a sustainable yield.", field: "outlier" });
  }

  // AVOID — forecast collapse / collapsed APY / illiquid exit.
  if (pClass === "Down" && pProb != null && pProb >= T.DOWN_PROB_AVOID) {
    worse("AVOID");
    score += 35;
    reasons.push({ code: "forecast_down_high_conf", detail: `DefiLlama's model forecasts the APY trending DOWN with ${pProb}% confidence (≥${T.DOWN_PROB_AVOID}%).`, field: "predicted_class" });
  }
  if (apy30 != null && apy30 <= T.APY_30D_COLLAPSE) {
    worse("AVOID");
    score += 30;
    reasons.push({ code: "apy_collapsed_30d", detail: `APY has fallen ${apy30.toFixed(1)}% over 30d (≤${T.APY_30D_COLLAPSE}%) — the yield that made this pool attractive is largely gone.`, field: "apyPct30D" });
  }
  if (tvl < T.TVL_ILLIQUID) {
    worse("AVOID");
    score += 25;
    reasons.push({ code: "illiquid_tvl", detail: `TVL is only $${Math.round(tvl).toLocaleString("en-US")} (<$${T.TVL_ILLIQUID.toLocaleString("en-US")}) — too thin to enter and exit a meaningful position safely.`, field: "tvlUsd" });
  }

  // DECAYING — meaningful negative trend or volatile APY.
  if (apy7 != null && apy7 <= T.APY_7D_DECAY) {
    worse("DECAYING");
    score += 18;
    reasons.push({ code: "apy_decaying_7d", detail: `APY is down ${apy7.toFixed(1)}% over 7d (≤${T.APY_7D_DECAY}%) — a near-term downtrend.`, field: "apyPct7D" });
  } else if (apy30 != null && apy30 <= T.APY_30D_DECAY && apy30 > T.APY_30D_COLLAPSE) {
    worse("DECAYING");
    score += 12;
    reasons.push({ code: "apy_decaying_30d", detail: `APY is down ${apy30.toFixed(1)}% over 30d (≤${T.APY_30D_DECAY}%) — a sustained downtrend.`, field: "apyPct30D" });
  }
  if (pClass === "Down" && (pProb == null || pProb < T.DOWN_PROB_AVOID)) {
    worse("DECAYING");
    score += 10;
    reasons.push({ code: "forecast_down", detail: `DefiLlama's model forecasts the APY trending DOWN${pProb != null ? ` (${pProb}% confidence)` : ""}.`, field: "predicted_class" });
  }
  if (sigma != null && sigma >= T.SIGMA_VOLATILE) {
    worse("DECAYING");
    score += 8;
    reasons.push({ code: "volatile_apy", detail: `APY volatility (sigma ${sigma.toFixed(2)}) is high (≥${T.SIGMA_VOLATILE}) — the return is unstable.`, field: "sigma" });
  }

  // Impermanent-loss drag — a modifier, flagged whenever material.
  if (il7 != null && Math.abs(il7) >= T.IL7D_HIGH) {
    score += 10;
    reasons.push({ code: "impermanent_loss", detail: `7-day impermanent loss is ${il7.toFixed(1)}% — LP exposure is eroding principal; net return is below the headline APY.`, field: "il7d" });
    if (verdict === "SUSTAINABLE") worse("DECAYING");
  } else if (pool.ilRisk === "yes" && verdict === "SUSTAINABLE") {
    reasons.push({ code: "il_risk_flag", detail: "Pool carries impermanent-loss risk (non-stable pair) — size accordingly.", field: "ilRisk" });
  }

  if (reasons.length === 0) {
    reasons.push({ code: "stable_sustainable", detail: "Stable-or-up forecast, APY trend intact, adequate liquidity — no decay, outlier or liquidity flags triggered.", field: "predicted_class" });
  }

  return {
    pool: pool.pool,
    project: pool.project,
    chain: pool.chain,
    symbol: pool.symbol,
    verdict,
    risk_score: Math.max(0, Math.min(100, Math.round(score))),
    reasons,
    apy,
    apyPct7D: apy7,
    apyPct30D: apy30,
    il7d: il7,
    ilRisk: pool.ilRisk,
    sigma,
    risk_adjusted_apy: num(pool.risk_adjusted_apy),
    predicted: { class: pClass, probability: pProb },
    tvlUsd: tvl,
  };
}

// Compact per-row decision tag for the /defi/yields list — the SUSTAINABLE |
// DECAYING | OUTLIER | AVOID label + 0-100 risk_score ONLY (never the field-cited
// reasons, predicted block, honeypot pointer or rotation math — those stay in the
// paid $0.01 /defi/yield-entry-verdict and /defi/yield-rotation). This is the
// eval-legible moat: a routing agent comparing yield feeds sees our rows already
// carry a go/no-go decision, the raw rivals' (Askew, Yield.xyz, DefiLlama /pools)
// don't. Pure, no network — reuses the pool's own DefiLlama fields. Returns null
// when apy is non-finite (a junk reading must not emit a false decision).
export function yieldRowVerdict(
  p: YieldPool,
): { verdict: YieldEntryVerdict; risk_score: number } | null {
  if (typeof p.apy !== "number" || !Number.isFinite(p.apy)) return null;
  const r = computeYieldEntryVerdict(p);
  return { verdict: r.verdict, risk_score: r.risk_score };
}

// Attach the compact decision tag to each row of a /defi/yields result (degrade-open:
// a row whose apy is non-finite keeps its full fields, just without a verdict).
export function tagYieldRowsWithVerdict<T extends YieldPool>(rows: T[]): T[] {
  return rows.map((p) => {
    const v = yieldRowVerdict(p);
    return v ? { ...p, verdict: v.verdict, risk_score: v.risk_score } : p;
  });
}

// GET /defi/yield-entry-verdict — paid ($0.01). The per-pool go/no-go on the
// proven-demand /defi/yields lane: pass the pool id from a /defi/yields row and
// get a packaged SUSTAINABLE | DECAYING | OUTLIER | AVOID verdict + risk score +
// field-cited reasons. The 200-envelope middleware auto-injects _greyridge.see_also
// pointing the same cohort at the token honeypot check + top data sibling.
app.get("/defi/yield-entry-verdict", async (c) => {
  const pool = (c.req.query("pool") || "").trim();
  if (!pool) {
    return c.json(
      { error: "pool required — pass ?pool=<DefiLlama poolId> (the 'pool' field from GET /defi/yields)." },
      { status: 400 },
    );
  }
  const token = (c.req.query("token") || "").trim();
  try {
    const p = await fetchDefiPoolById(pool);
    if (!p) {
      return c.json({ pool, verdict: null, error: "pool not found — the poolId is not in DefiLlama's current universe. Use the 'pool' field from GET /defi/yields." });
    }
    const result = computeYieldEntryVerdict(p);
    const body: Record<string, unknown> = { ...result };
    // Optional underlying-token hook: we don't run the honeypot sim inline (keeps
    // the verdict fast + the token check is a distinct paid verdict), but when a
    // Base token is supplied we surface the explicit next-call pointer so the
    // caller folds rug/honeypot risk into the decision.
    if (token && /^0x[a-fA-F0-9]{40}$/.test(token)) {
      body.token_safety_hint = {
        token,
        note: "Underlying-token honeypot/rug risk is NOT included in this pool verdict. Run GET /chain/token-report?token=" + token + " ($0.01) before committing funds.",
        resource: CANONICAL_ORIGIN + "/chain/token-report?token=" + token,
      };
    }
    console.log(
      JSON.stringify({ event: "paid_request", endpoint: "/defi/yield-entry-verdict", pool, verdict: result.verdict, risk_score: result.risk_score, ts: new Date().toISOString() }),
    );
    const rail = c.get("rail") ?? "x402-paid";
    fireAndForget(c, trackPaidRequest("GET /defi/yield-entry-verdict", rail, makeUsageCounter(c.env)));
    return c.json(body);
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// Free keyless preview — the verdict for a demo pool so an agent can sample the
// packaged output before paying, mirroring /defi/safe-yields/preview.
app.get("/defi/yield-entry-verdict/preview", async (c) => {
  const pool = (c.req.query("pool") || "").trim();
  // No ?pool= → the unchanged top-TVL demo verdict (what catalogs/marketing link).
  if (!pool) {
    try {
      const sample = await fetchDefiYields(1, undefined, undefined, false);
      if (sample.length === 0) {
        return c.json({ preview: null, note: "No demo pool available right now.", status: 502 }, { status: 502 });
      }
      const result = computeYieldEntryVerdict(sample[0]);
      return c.json({
        preview: result,
        note: "Free sample verdict for the current top-TVL pool. Pass ?pool=<poolId from /defi/yields> to get the verdict for YOUR pool free (3/IP/day), or GET /defi/yield-entry-verdict?pool=<poolId> ($0.01) — packaged SUSTAINABLE|DECAYING|OUTLIER|AVOID + risk score + field-cited reasons, keyless x402 on Base.",
      });
    } catch (e) {
      return c.json({ error: (e as Error).message }, { status: 502 });
    }
  }
  // ?pool= present → the caller wants the verdict for their own pool.
  const paidUrl = paidUrlFrom(c);
  try {
    const t = await trialQuota(c, "yieldverdict");
    if (t.exhausted) {
      const sample = await fetchDefiYields(1, undefined, undefined, false);
      const demo = sample.length ? computeYieldEntryVerdict(sample[0]) : null;
      return c.json({ preview: demo, trial: { full_pulls_left_today: 0 }, paid: paidUrl, price_usdc: "0.01", note: "Free per-pool trial exhausted for today (3/IP/day); showing the top-TVL demo verdict. Paid (unmetered): GET /defi/yield-entry-verdict?pool=<poolId> ($0.01)." });
    }
    const p = await fetchDefiPoolById(pool);
    if (!p) {
      // Pool-not-found doesn't consume real value — refund the trial so a typo'd
      // poolId never burns one of the 3 genuine pulls.
      await refundTrial(c, "yieldverdict");
      return c.json({ pool, verdict: null, error: "pool not found — the poolId is not in DefiLlama's current universe. Use the 'pool' field from GET /defi/yields.", paid: paidUrl });
    }
    const result = computeYieldEntryVerdict(p);
    return c.json({
      data: result,
      trial: t.left === null ? undefined : { full_pulls_left_today: t.left },
      paid: paidUrl,
      price_usdc: "0.01",
      note: `Free per-pool trial — the complete packaged verdict for YOUR pool${t.left === null ? "" : ` (${t.left} left today, 3/IP/day)`}. Wire it unmetered: GET /defi/yield-entry-verdict?pool=<poolId> ($0.01), keyless x402 on Base.`,
    });
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// Fetch several DefiLlama pools by id in ONE upstream call (the /pools endpoint
// has no id filter, so a rotation that compares two pools must not fetch-all
// twice). Returns a map poolId → normalized pool (missing ids absent).
export async function fetchDefiPoolsByIds(poolIds: string[]): Promise<Map<string, YieldPool>> {
  const res = await fetch("https://yields.llama.fi/pools", { headers: { accept: "application/json" } });
  if (!res.ok) {
    throw new Error(`DefiLlama yields upstream error: ${res.status}`);
  }
  const raw = (await res.json()) as { status: string; data: DefiLlamaPool[] };
  const want = new Set(poolIds);
  const out = new Map<string, YieldPool>();
  for (const p of raw.data) {
    if (want.has(p.pool)) out.set(p.pool, normalizeDefiLlamaPool(p));
  }
  return out;
}

// ── /defi/yield-rotation ($0.01) — the rotate-or-stay decision ───────────────
// An agent already holding an LP position re-makes ONE decision continuously as
// APYs drift: is pool B enough better than my current pool A to move, AFTER the
// roundtrip cost and the risk change? DefiLlama's free /pools and every x402
// yield seller give the two raw APYs; none packages the net-of-cost, risk-aware
// ROTATE | STAY | MARGINAL verdict. Pure + deterministic over both pools' own
// DefiLlama fields + a transparent gas/breakeven model (every threshold a named
// constant, every reason field-cited). This is the repeat-query sibling to the
// one-shot /defi/yield-entry-verdict: an open position is re-checked, not entered
// once.
export type YieldRotationVerdict = "ROTATE" | "STAY" | "MARGINAL";
export interface YieldRotationLeg {
  pool: string;
  project: string;
  chain: string;
  symbol: string;
  apy: number | null;
  verdict: YieldEntryVerdict;
  risk_score: number;
  tvlUsd: number;
}
export interface YieldRotationResult {
  verdict: YieldRotationVerdict;
  from: YieldRotationLeg;
  to: YieldRotationLeg;
  notional_usd: number;
  apy_delta_pct: number | null;
  risk_score_delta: number;
  rotation_cost_bps: number;
  rotation_cost_usd: number;
  breakeven_days: number | null;          // null = no positive pickup → never pays back
  net_gain_first_year_usd: number | null; // extra yield minus rotation cost over 12mo
  reasons: YieldEntryReason[];
}

export const YIELD_ROTATION_THRESHOLDS = {
  ROTATION_COST_BPS: 30,          // roundtrip exit+enter estimate (≈2 swaps @ ~15bps on Base) applied to notional
  BREAKEVEN_ROTATE_DAYS: 30,      // pickup recoups the cost within this → clearly worth moving
  BREAKEVEN_MARGINAL_DAYS: 90,    // recoups within this → marginal; beyond → STAY
  RISK_DELTA_MATERIAL: 20,        // to.risk_score − from.risk_score ≥ this → materially riskier target
  MIN_APY_PICKUP_PCT: 1.0,        // |apyDelta| below this → not worth the rotation cost
} as const;

export function computeYieldRotation(from: YieldPool, to: YieldPool, notionalUsd: number): YieldRotationResult {
  const T = YIELD_ROTATION_THRESHOLDS;
  const fv = computeYieldEntryVerdict(from);
  const tv = computeYieldEntryVerdict(to);
  const reasons: YieldEntryReason[] = [];
  const num = (v: number | null | undefined): number | null =>
    typeof v === "number" && Number.isFinite(v) ? v : null;
  const r2 = (x: number) => Math.round(x * 100) / 100;
  const r1 = (x: number) => Math.round(x * 10) / 10;

  const fromApy = num(from.apy);
  const toApy = num(to.apy);
  const apyDelta = fromApy != null && toApy != null ? toApy - fromApy : null;
  const riskDelta = tv.risk_score - fv.risk_score;
  const costUsd = (notionalUsd * T.ROTATION_COST_BPS) / 10000;

  let breakevenDays: number | null = null;
  let netGainYr: number | null = null;
  if (apyDelta != null) {
    netGainYr = (notionalUsd * apyDelta) / 100 - costUsd;
    if (apyDelta > 0) {
      const dailyGain = (notionalUsd * (apyDelta / 100)) / 365;
      breakevenDays = dailyGain > 0 ? costUsd / dailyGain : null;
    }
  }

  const leg = (p: YieldPool, v: YieldEntryVerdictResult): YieldRotationLeg => ({
    pool: p.pool, project: p.project, chain: p.chain, symbol: p.symbol,
    apy: num(p.apy), verdict: v.verdict, risk_score: v.risk_score, tvlUsd: num(p.tvlUsd) ?? 0,
  });

  let verdict: YieldRotationVerdict = "STAY";
  const materialRisk = riskDelta >= T.RISK_DELTA_MATERIAL;

  if (tv.verdict === "AVOID" || tv.verdict === "OUTLIER") {
    // Never rotate INTO a pool our own entry verdict rejects, whatever the pickup.
    verdict = "STAY";
    reasons.push({ code: "target_unsafe", detail: `Target pool verdict is ${tv.verdict} (risk ${tv.risk_score}/100) — do not rotate into it regardless of the APY pickup.`, field: "to.verdict" });
  } else if (apyDelta == null) {
    reasons.push({ code: "apy_unknown", detail: "APY is missing on one leg — the yield pickup cannot be quantified; hold the current position.", field: "apy" });
  } else if (apyDelta < T.MIN_APY_PICKUP_PCT) {
    reasons.push({ code: "no_yield_pickup", detail: `Target APY is ${apyDelta >= 0 ? "only " : ""}${apyDelta.toFixed(2)}% ${apyDelta >= 0 ? "higher" : "lower"} than the current pool (<${T.MIN_APY_PICKUP_PCT}% pickup) — not worth the rotation cost.`, field: "apy" });
  } else if (breakevenDays != null && breakevenDays <= T.BREAKEVEN_ROTATE_DAYS && !materialRisk) {
    verdict = "ROTATE";
    reasons.push({ code: "pickup_pays_off", detail: `Target pays ${apyDelta.toFixed(2)}% more APY; at $${Math.round(notionalUsd).toLocaleString("en-US")} the ~$${r2(costUsd)} rotation cost is recouped in ${Math.ceil(breakevenDays)}d (≤${T.BREAKEVEN_ROTATE_DAYS}d) with no material risk increase.`, field: "breakeven_days" });
  } else if (breakevenDays != null && breakevenDays > T.BREAKEVEN_MARGINAL_DAYS) {
    reasons.push({ code: "slow_breakeven", detail: `The rotation cost takes ${Math.ceil(breakevenDays)}d to recoup (>${T.BREAKEVEN_MARGINAL_DAYS}d) — the APY edge is too thin at this notional to justify moving.`, field: "breakeven_days" });
  } else {
    verdict = "MARGINAL";
    if (materialRisk) {
      reasons.push({ code: "riskier_target", detail: `Target is materially riskier (risk ${tv.risk_score} vs ${fv.risk_score}, +${riskDelta}) — the ${apyDelta.toFixed(2)}% pickup may not compensate for the added risk.`, field: "risk_score" });
    }
    reasons.push({ code: "marginal_edge", detail: `A real but not decisive edge: ${apyDelta.toFixed(2)}% pickup, breakeven ~${breakevenDays != null ? Math.ceil(breakevenDays) + "d" : "n/a"}. Rotate only if you expect the target's APY to hold.`, field: "breakeven_days" });
  }

  // Always fold the target's own decay signal in when we're not already staying.
  if (tv.verdict === "DECAYING" && verdict !== "STAY") {
    reasons.push({ code: "target_decaying", detail: "The target pool's own APY trend is DECAYING — the pickup may not persist; re-check before committing.", field: "to.verdict" });
  }

  return {
    verdict,
    from: leg(from, fv),
    to: leg(to, tv),
    notional_usd: notionalUsd,
    apy_delta_pct: apyDelta != null ? r2(apyDelta) : null,
    risk_score_delta: riskDelta,
    rotation_cost_bps: T.ROTATION_COST_BPS,
    rotation_cost_usd: r2(costUsd),
    breakeven_days: breakevenDays != null ? r1(breakevenDays) : null,
    net_gain_first_year_usd: netGainYr != null ? r2(netGainYr) : null,
    reasons,
  };
}

// Parse + clamp the ?notional= position size (USD). Default $10k; floor $100,
// ceiling $10M. Degrade-open: junk → default, never a 400.
function parseRotationNotional(raw: string | undefined): number {
  const n = raw ? Number(raw) : NaN;
  if (!Number.isFinite(n) || n <= 0) return 10_000;
  return Math.max(100, Math.min(10_000_000, n));
}

// GET /defi/yield-rotation — paid ($0.01). Pass ?from=<poolId you hold>&to=<poolId
// you're considering> (&notional=<usd>, default 10000) → ROTATE | STAY | MARGINAL
// net of a transparent roundtrip cost + risk change. One upstream DefiLlama call
// covers both legs.
app.get("/defi/yield-rotation", async (c) => {
  const from = (c.req.query("from") || "").trim();
  const to = (c.req.query("to") || "").trim();
  if (!from || !to) {
    return c.json(
      { error: "from and to required — pass ?from=<poolId you currently hold>&to=<poolId you're considering> (the 'pool' field from GET /defi/yields). Optional &notional=<usd> (default 10000)." },
      { status: 400 },
    );
  }
  if (from === to) {
    return c.json({ error: "from and to are the same pool — nothing to rotate." }, { status: 400 });
  }
  const notional = parseRotationNotional(c.req.query("notional"));
  try {
    const pools = await fetchDefiPoolsByIds([from, to]);
    const pf = pools.get(from);
    const pt = pools.get(to);
    if (!pf || !pt) {
      const missing = [!pf ? from : null, !pt ? to : null].filter(Boolean).join(", ");
      return c.json({ from, to, verdict: null, error: `pool not found (${missing}) — the poolId is not in DefiLlama's current universe. Use the 'pool' field from GET /defi/yields.` });
    }
    const result = computeYieldRotation(pf, pt, notional);
    console.log(
      JSON.stringify({ event: "paid_request", endpoint: "/defi/yield-rotation", from, to, notional, verdict: result.verdict, ts: new Date().toISOString() }),
    );
    const rail = c.get("rail") ?? "x402-paid";
    fireAndForget(c, trackPaidRequest("GET /defi/yield-rotation", rail, makeUsageCounter(c.env)));
    return c.json(result);
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// Free keyless preview — a demo rotation between the two top-TVL pools so an agent
// can sample the packaged decision before paying; with ?from=&to= it runs YOUR
// pair 3/IP/day (trial), mirroring /defi/yield-entry-verdict/preview.
app.get("/defi/yield-rotation/preview", async (c) => {
  const from = (c.req.query("from") || "").trim();
  const to = (c.req.query("to") || "").trim();
  const notional = parseRotationNotional(c.req.query("notional"));
  // No pair → demo rotation (top-2 TVL pools), what catalogs/marketing link.
  if (!from || !to) {
    try {
      const sample = await fetchDefiYields(2, undefined, undefined, false);
      if (sample.length < 2) {
        return c.json({ preview: null, note: "No demo pair available right now.", status: 502 }, { status: 502 });
      }
      const result = computeYieldRotation(sample[0], sample[1], notional);
      return c.json({
        preview: result,
        note: "Free demo rotation between the two top-TVL pools. Pass ?from=<poolId you hold>&to=<poolId you're considering> to run YOUR pair free (3/IP/day), or GET /defi/yield-rotation?from=…&to=… ($0.01) — ROTATE|STAY|MARGINAL net of a transparent roundtrip cost + risk change, keyless x402 on Base.",
      });
    } catch (e) {
      return c.json({ error: (e as Error).message }, { status: 502 });
    }
  }
  const paidUrl = paidUrlFrom(c);
  if (from === to) {
    return c.json({ preview: null, error: "from and to are the same pool — nothing to rotate.", paid: paidUrl });
  }
  try {
    const t = await trialQuota(c, "yieldrotation");
    if (t.exhausted) {
      const sample = await fetchDefiYields(2, undefined, undefined, false);
      const demo = sample.length >= 2 ? computeYieldRotation(sample[0], sample[1], notional) : null;
      return c.json({ preview: demo, trial: { full_pulls_left_today: 0 }, paid: paidUrl, price_usdc: "0.01", note: "Free rotation trial exhausted for today (3/IP/day); showing the top-TVL demo. Paid (unmetered): GET /defi/yield-rotation?from=…&to=… ($0.01)." });
    }
    const pools = await fetchDefiPoolsByIds([from, to]);
    const pf = pools.get(from);
    const pt = pools.get(to);
    if (!pf || !pt) {
      // Not-found doesn't consume real value — refund the trial.
      await refundTrial(c, "yieldrotation");
      const missing = [!pf ? from : null, !pt ? to : null].filter(Boolean).join(", ");
      return c.json({ from, to, verdict: null, error: `pool not found (${missing}) — use the 'pool' field from GET /defi/yields.`, paid: paidUrl });
    }
    const result = computeYieldRotation(pf, pt, notional);
    return c.json({
      data: result,
      trial: t.left === null ? undefined : { full_pulls_left_today: t.left },
      paid: paidUrl,
      price_usdc: "0.01",
      note: `Free rotation trial — the complete ROTATE|STAY|MARGINAL decision for YOUR pair${t.left === null ? "" : ` (${t.left} left today, 3/IP/day)`}. Wire it unmetered: GET /defi/yield-rotation?from=…&to=… ($0.01), keyless x402 on Base.`,
    });
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// ── /security/epss-movers ($0.01) — EPSS velocity feed ──────────────────────
// The uncontested axis on the security lane: WHAT CHANGED, not a point lookup.
// Optional ?limit=<N> (top-N by current EPSS to scan, default 100, max 200) and
// ?rising=<delta> / ?level=<0..1> to tune thresholds. One upstream call.
function parseEpssLimit(raw: string | undefined): number {
  const n = parseInt((raw ?? "").trim(), 10);
  if (!Number.isFinite(n) || n <= 0) return 100;
  return Math.min(n, 200);
}
function parseUnit(raw: string | undefined, fallback: number): number {
  const n = parseFloat((raw ?? "").trim());
  if (!Number.isFinite(n) || n < 0 || n > 1) return fallback;
  return n;
}
async function buildEpssMovers(
  limit: number,
  risingDelta: number,
  level: number,
): Promise<EpssMoversResult> {
  const { rows, total } = await fetchEpssMovers(limit, level);
  const kev = await isInKev(rows.map((r) => r.cve));
  const result = computeEpssMovers(rows, kev, {
    risingDelta7d: risingDelta,
    actionLevel: level,
  });
  result.universe_total = total;
  return result;
}

app.get("/security/epss-movers", async (c) => {
  const limit = parseEpssLimit(c.req.query("limit"));
  const risingDelta = parseUnit(c.req.query("rising"), EPSS_RISING_DELTA_7D);
  const level = parseUnit(c.req.query("level"), EPSS_ACTION_LEVEL);
  try {
    const result = await buildEpssMovers(limit, risingDelta, level);
    if (result.universe_scanned === 0) {
      return c.json({ ...result, error: "EPSS feed unavailable upstream right now — try again shortly." }, { status: 502 });
    }
    console.log(
      JSON.stringify({ event: "paid_request", endpoint: "/security/epss-movers", limit, rising: result.rising.length, crossed: result.crossed_action_level.length, ts: new Date().toISOString() }),
    );
    const rail = c.get("rail") ?? "x402-paid";
    fireAndForget(c, trackPaidRequest("GET /security/epss-movers", rail, makeUsageCounter(c.env)));
    return c.json(result);
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// Free keyless preview — a demo over the top-20 EPSS CVEs so an agent can sample
// the "what moved" shape before paying; with ?limit= it runs YOUR scan 3/IP/day.
app.get("/security/epss-movers/preview", async (c) => {
  const hasArgs = !!(c.req.query("limit") || c.req.query("rising") || c.req.query("level"));
  const risingDelta = parseUnit(c.req.query("rising"), EPSS_RISING_DELTA_7D);
  const level = parseUnit(c.req.query("level"), EPSS_ACTION_LEVEL);
  const paidUrl = paidUrlFrom(c);
  // No args → small demo scan (top-20), what catalogs/marketing link.
  if (!hasArgs) {
    try {
      const demo = await buildEpssMovers(20, risingDelta, level);
      return c.json({
        preview: { ...demo, top_movers: demo.top_movers.slice(0, 5), rising: demo.rising.slice(0, 5), crossed_action_level: demo.crossed_action_level.slice(0, 5), new_kev_high_epss: demo.new_kev_high_epss.slice(0, 5) },
        note: "Free demo over the top-20 EPSS CVEs (lists capped at 5). Pass ?limit=<N up to 200> to scan deeper free (3/IP/day), or GET /security/epss-movers?limit=100 ($0.01) — the full EPSS velocity feed (rising / crossed-threshold / KEV-and-rising), keyless x402 on Base.",
      });
    } catch (e) {
      return c.json({ error: (e as Error).message }, { status: 502 });
    }
  }
  const limit = parseEpssLimit(c.req.query("limit"));
  try {
    const t = await trialQuota(c, "epssmovers");
    if (t.exhausted) {
      const demo = await buildEpssMovers(20, risingDelta, level);
      return c.json({ preview: { ...demo, top_movers: demo.top_movers.slice(0, 5) }, trial: { full_pulls_left_today: 0 }, paid: paidUrl, price_usdc: "0.01", note: "Free EPSS-movers trial exhausted for today (3/IP/day); showing the top-20 demo. Paid (unmetered): GET /security/epss-movers?limit=100 ($0.01)." });
    }
    const result = await buildEpssMovers(limit, risingDelta, level);
    if (result.universe_scanned === 0) {
      await refundTrial(c, "epssmovers");
      return c.json({ data: null, error: "EPSS feed unavailable upstream right now — try again shortly.", paid: paidUrl });
    }
    return c.json({
      data: result,
      trial: t.left === null ? undefined : { full_pulls_left_today: t.left },
      paid: paidUrl,
      price_usdc: "0.01",
      note: `Free EPSS-movers trial — the complete velocity feed for your scan${t.left === null ? "" : ` (${t.left} left today, 3/IP/day)`}. Wire it unmetered: GET /security/epss-movers?limit=${limit} ($0.01), keyless x402 on Base.`,
    });
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

interface DefiLlamaPriceCoin {
  price: number;
  symbol: string;
  timestamp: number;
  confidence: number;
}

interface TokenPrice {
  id: string;
  symbol: string;
  price: number;
  change_24h: number | null;
  confidence: number;
  timestamp: number;
}

const COINGECKO_ID_RE = /^[a-z0-9-]{1,40}$/;

// Common ticker-symbol → CoinGecko id aliases. An LLM asked "what's ETH trading
// at" calls with "ETH", not the CoinGecko slug "ethereum", so without this the
// most natural query 400s on a paid route. This is a convenience alias table,
// not a gate: an unknown symbol passes through unchanged and is validated as an
// id (degrade-open), so real CoinGecko ids keep working exactly as before.
const COIN_ALIASES: Record<string, string> = {
  btc: "bitcoin",
  eth: "ethereum",
  weth: "weth",
  sol: "solana",
  bnb: "binancecoin",
  xrp: "ripple",
  ada: "cardano",
  doge: "dogecoin",
  avax: "avalanche-2",
  dot: "polkadot",
  matic: "matic-network",
  pol: "matic-network",
  link: "chainlink",
  uni: "uniswap",
  ltc: "litecoin",
  trx: "tron",
  atom: "cosmos",
  near: "near",
  apt: "aptos",
  arb: "arbitrum",
  op: "optimism",
  usdc: "usd-coin",
  usdt: "tether",
  dai: "dai",
  wbtc: "wrapped-bitcoin",
  cbbtc: "coinbase-wrapped-btc",
  steth: "staked-ether",
  aave: "aave",
  mkr: "maker",
  ldo: "lido-dao",
  crv: "curve-dao-token",
  snx: "havven",
  comp: "compound-governance-token",
  aero: "aerodrome-finance",
  degen: "degen-base",
  pepe: "pepe",
  shib: "shiba-inu",
  ena: "ethena",
  sui: "sui",
  ton: "the-open-network",
  hype: "hyperliquid",
};

/**
 * Normalize a caller's coin list to CoinGecko ids: trim, lowercase, and map a
 * known ticker symbol to its slug. Unknown tokens pass through lowercased so a
 * genuine CoinGecko id still resolves (and a truly invalid one still 400s at
 * the validation step, with the same clear error).
 */
function resolveCoinIds(ids: string[]): string[] {
  return ids.map((raw) => {
    const k = raw.trim().toLowerCase();
    return COIN_ALIASES[k] ?? k;
  });
}

// Best-effort 24h % change — same host as the price call (coins.llama.fi), a
// separate endpoint, so an upstream failure here never fails the price fetch.
async function fetchTokenPriceChanges(ids: string[]): Promise<Record<string, number | null>> {
  const result: Record<string, number | null> = {};
  try {
    const path = ids.map((id) => `coingecko:${id}`).join(",");
    const res = await meteredFetch(`https://coins.llama.fi/percentage/${path}?period=24h`, {
      headers: { accept: "application/json" },
    }, "optional");
    if (!res.ok) return result;
    const raw = (await res.json()) as { coins: Record<string, number> };
    for (const id of ids) {
      const v = raw.coins[`coingecko:${id}`];
      result[id] = typeof v === "number" && Number.isFinite(v) ? v : null;
    }
  } catch {
    // Keep whatever was resolved (possibly empty) — non-fatal enrichment.
  }
  return result;
}

async function fetchTokenPrices(ids: string[], opts?: { withChange?: boolean }): Promise<TokenPrice[]> {
  const path = ids.map((id) => `coingecko:${id}`).join(",");
  // withChange:false skips the 24h-change lookup — a second subrequest whose value
  // getEthUsd (spot price for liquidity USD) never reads.
  const [res, changes] = await Promise.all([
    meteredFetch(`https://coins.llama.fi/prices/current/${path}`, { headers: { accept: "application/json" } }, "core"),
    opts?.withChange === false ? Promise.resolve({} as Record<string, number | null>) : fetchTokenPriceChanges(ids),
  ]);
  if (!res.ok) {
    throw new Error(`DefiLlama prices upstream error: ${res.status}`);
  }
  const raw = (await res.json()) as { coins: Record<string, DefiLlamaPriceCoin> };

  return ids
    .map((id) => {
      const coin = raw.coins[`coingecko:${id}`];
      if (!coin) return null;
      return {
        id,
        symbol: coin.symbol,
        price: coin.price,
        change_24h: changes[id] ?? null,
        confidence: coin.confidence,
        timestamp: coin.timestamp,
      };
    })
    .filter((c): c is TokenPrice => c !== null);
}

// --- The TIME moat: a per-series tick archive in KV ------------------------
// Point-in-time rivals cannot reconstruct history they never stored. We record a
// compact, size-bounded, write-throttled tick per DATA series on serve, and the
// paid payload leads with its provenance: tracked_since, tick count and the
// trajectory since we first saw it. Every function here is degrade-open — a KV
// outage or write-limit returns no provenance block, never a 500 and never a
// broken DATA answer (same discipline as trialQuota).
const ARCH_SCHEMA = 1;

// Look up the git-committed baked archive for a series+id (reliable, cron-written,
// CI-deployed). Shape guard so a malformed snapshot never throws into a handler.
function bakedRecord(series: string, id: string): ProvRecord | null {
  try {
    const s = (PROVENANCE_SNAPSHOT as any)?.series?.[series]?.[id];
    if (s && Array.isArray(s.ticks)) return s as ProvRecord;
  } catch {
    /* fall through */
  }
  return null;
}

async function archiveProvenance(
  c: any,
  series: string,
  id: string,
  value: number,
): Promise<ProvSummary | null> {
  const now = Date.now();
  const baked = bakedRecord(series, id);
  const kv = c.env?.API_KEYS;
  const key = `arch:${series}:${id}`;

  // Best-effort live KV record — fresher intraday ticks when writes succeed, but
  // we never depend on it (free-tier put() is daily-capped + eventually
  // consistent). The committed snapshot is the reliable floor.
  let kvRec: ProvRecord | null = null;
  if (kv) {
    try {
      const raw = await kv.get(key);
      kvRec = raw ? (JSON.parse(raw) as ProvRecord) : null;
    } catch {
      kvRec = null;
    }
  }

  // Merge committed + live history, then append this request's live value as the
  // newest tick (throttled vs the merged last). The summary returned to the
  // buyer is built from this in-memory record, so it is correct even if the KV
  // write below fails or never propagates.
  const base = mergeRecords(baked, kvRec);
  const { rec: updated, appended } = appendTick(base, now, value);

  if (kv && appended) {
    try {
      await kv.put(key, JSON.stringify({ v: ARCH_SCHEMA, ...updated }));
    } catch {
      /* degrade-open: persistence lives in the committed snapshot regardless */
    }
  }
  return summarizeProvenance(updated, now);
}

app.get("/crypto/prices", async (c) => {
  const coinsParam = c.req.query("coins") || "bitcoin,ethereum,solana";
  const ids = resolveCoinIds(coinsParam.split(",").map((s) => s.trim()).filter(Boolean));

  if (ids.length === 0) {
    return c.json({ error: "coins query param must contain at least one CoinGecko id or ticker symbol" }, { status: 400 });
  }
  if (ids.length > 25) {
    return c.json({ error: "coins query param accepts at most 25 ids" }, { status: 400 });
  }
  const invalid = ids.filter((id) => !COINGECKO_ID_RE.test(id));
  if (invalid.length > 0) {
    return c.json({ error: `invalid coingecko id(s): ${invalid.join(", ")}` }, { status: 400 });
  }

  try {
    const prices = await fetchTokenPrices(ids);

    // Lead with provenance — the one axis no point-in-time rival can match. Each
    // item carries the archive we hold for that coin (tracked_since, ticks,
    // trajectory, change-since-first). Writes are throttled + degrade-open, so an
    // enriched array is best-effort: an item without `.provenance` still has its
    // price (never a breaking change to the array shape).
    const enriched = await Promise.all(
      prices.map(async (p) => {
        const prov = await archiveProvenance(c, "price", p.id, p.price);
        return prov ? { ...p, provenance: prov } : p;
      }),
    );

    console.log(
      JSON.stringify({
        event: "paid_request",
        endpoint: "/crypto/prices",
        coins: ids,
        count: prices.length,
        ts: new Date().toISOString(),
      }),
    );
    const rail = c.get("rail") ?? "x402-paid";
    fireAndForget(c, trackPaidRequest("GET /crypto/prices", rail, makeUsageCounter(c.env)));

    return c.json(enriched);
  } catch (e) {
    return c.json({ error: (e as Error).message }, { status: 502 });
  }
});

// ---------------------------------------------------------------------------
// Internal USD price helpers — the moat OneSource (ETH-only, no price oracle)
// can't match. Cross-call our own DefiLlama fetch logic in-process (never a
// paid x402 sub-call, never a second upstream host), cached per isolate with
// a short TTL: long enough to spare repeat /chain/* calls a redundant fetch,
// short enough that a busy isolate never serves a stale USD figure.
// ---------------------------------------------------------------------------

const USD_PRICE_TTL_MS = 30_000;

let ethUsdCache: { price: number; ts: number } | null = null;

async function getEthUsd(): Promise<number | null> {
  const now = Date.now();
  if (ethUsdCache && now - ethUsdCache.ts < USD_PRICE_TTL_MS) return ethUsdCache.price;
  try {
    const [eth] = await fetchTokenPrices(["ethereum"], { withChange: false });
    if (!eth || !Number.isFinite(eth.price)) return ethUsdCache?.price ?? null;
    ethUsdCache = { price: eth.price, ts: now };
    return eth.price;
  } catch {
    return ethUsdCache?.price ?? null; // stale-but-present beats a hard failure
  }
}

const tokenUsdCache = new Map<string, { price: number; ts: number }>();

// Base-chain ERC-20 price by contract address, via the same coins.llama.fi
// host as fetchTokenPrices (the `base:{address}` id form instead of
// `coingecko:{id}`). Not called by any route in this build; kept ready for
// token-level USD enrichment (e.g. /chain/token-balance).
async function getTokenUsd(contract: string): Promise<number | null> {
  const key = contract.toLowerCase();
  const now = Date.now();
  const cached = tokenUsdCache.get(key);
  if (cached && now - cached.ts < USD_PRICE_TTL_MS) return cached.price;
  try {
    const res = await fetch(`https://coins.llama.fi/prices/current/base:${key}`, {
      headers: { accept: "application/json" },
    });
    if (!res.ok) return cached?.price ?? null;
    const raw = (await res.json()) as { coins: Record<string, { price: number }> };
    const price = raw.coins[`base:${key}`]?.price;
    if (typeof price !== "number" || !Number.isFinite(price)) return cached?.price ?? null;
    tokenUsdCache.set(key, { price, ts: now });
    return price;
  } catch {
    return cached?.price ?? null;
  }
}

